export default [["q-fcps-pha4-01","The loading dose of a drug depends mainly on its:",["Volume of distribution","Clearance","Half-life","Bioavailability only"],"Loading dose equals the target concentration times the volume of distribution. Maintenance dose depends on clearance."],["q-fcps-pha4-02","Drug clearance determines the:",["Maintenance dose rate needed for a target steady-state concentration","Loading dose","Volume of distribution","Rate of absorption"],"At steady state the dosing rate equals clearance times the concentration."],["q-fcps-pha4-03","A partial agonist in the presence of a full agonist:",["Can reduce the overall response by competing for receptors","Always increases the response","Has no effect","Acts only on spare receptors"],"A partial agonist has lower intrinsic activity, so it displaces the full agonist and acts as a functional antagonist."],["q-fcps-pha4-04","A drug that gradually loses effect within minutes of repeated administration shows:",["Tachyphylaxis","Idiosyncrasy","Synergism","Hypersensitivity"],"Tachyphylaxis is rapid tolerance, for example to nasal decongestants and indirectly acting amines."],["q-fcps-pha4-05","Which of these is a CYP3A4 inhibitor that can raise statin levels and cause rhabdomyolysis?",["Clarithromycin","Rifampicin","Phenytoin","Carbamazepine"],"Macrolides such as clarithromycin and erythromycin, azole antifungals, grapefruit juice and ritonavir inhibit CYP3A4."],["q-fcps-pha4-06","Which of these is a potent enzyme inducer that can reduce the effectiveness of the oral contraceptive pill?",["St John's wort","Cimetidine","Ciprofloxacin","Fluconazole"],"St John's wort, rifampicin, phenytoin, carbamazepine and phenobarbital induce CYP enzymes."],["q-fcps-pha4-07","Slow acetylators are at increased risk of which adverse effect?",["Isoniazid neuropathy and drug-induced lupus","Warfarin resistance","Haemolysis","Malignant hyperthermia"],"N-acetyltransferase variants affect isoniazid, hydralazine and procainamide."],["q-fcps-pha4-08","A patient with poor CYP2D6 metabolism given codeine would have:",["Inadequate analgesia","Respiratory depression","Increased pain tolerance","Hepatotoxicity"],"Codeine is a prodrug converted to morphine by CYP2D6, so poor metabolisers gain little analgesia, and ultra-rapid metabolisers risk toxicity."],["q-fcps-pha4-09","Clopidogrel may be less effective in carriers of reduced-function alleles of:",["CYP2C19","CYP2D6","CYP3A4","CYP1A2"],"Clopidogrel needs CYP2C19 for activation."],["q-fcps-pha4-10","Which drug taken in the first trimester causes neural tube defects?",["Sodium valproate","Lithium","Warfarin","Tetracycline"],"Valproate carries a risk of spina bifida and lowers IQ. Warfarin causes a characteristic embryopathy with nasal hypoplasia, and lithium is linked to Ebstein anomaly."],["q-fcps-pha4-11","Thalidomide taken during pregnancy causes:",["Phocomelia","Neural tube defects","Teeth discolouration","Cleft palate only"],"Thalidomide interferes with limb development, and it is now used for myeloma and erythema nodosum leprosum under strict control."],["q-fcps-pha4-12","Fetal hydantoin syndrome is caused by:",["Phenytoin","Valproate","Lamotrigine","Levetiracetam"],"It includes craniofacial abnormalities, nail hypoplasia and growth deficiency."],["q-fcps-pha4-13","Isotretinoin is contraindicated in pregnancy because it causes:",["Craniofacial and cardiac malformations","Neonatal haemorrhage","Grey baby syndrome","Ototoxicity"],"Retinoids are potent teratogens, and pregnancy must be excluded before and during therapy."],["q-fcps-pha4-14","Which drug is used to treat glaucoma by causing miosis and contraction of the ciliary muscle?",["Pilocarpine","Atropine","Timolol","Phenylephrine"],"Pilocarpine opens the trabecular meshwork and increases aqueous outflow."],["q-fcps-pha4-15","Pralidoxime in organophosphate poisoning acts by:",["Reactivating acetylcholinesterase before ageing occurs","Blocking muscarinic receptors","Inhibiting nicotinic receptors","Chelating the poison"],"Pralidoxime regenerates the enzyme and should be given early, and atropine treats the muscarinic effects."],["q-fcps-pha4-16","Physostigmine is useful in anticholinergic poisoning because it:",["Crosses the blood-brain barrier and inhibits acetylcholinesterase","Blocks muscarinic receptors","Releases noradrenaline","Activates nicotinic channels directly"],"It is a tertiary amine and so reverses both central and peripheral antimuscarinic toxicity."],["q-fcps-pha4-17","Phenylephrine is a:",["Selective alpha-1 agonist","Beta-2 agonist","Alpha-2 antagonist","Dopamine agonist"],"It raises blood pressure by vasoconstriction, causing reflex bradycardia, and is used as a nasal decongestant and mydriatic."],["q-fcps-pha4-18","Isoprenaline acts on which receptors?",["Beta-1 and beta-2","Alpha-1 only","Alpha-2 only","Dopamine D1"],"It increases heart rate and contractility and causes vasodilatation, so diastolic pressure falls."],["q-fcps-pha4-19","At low doses (1 to 3 micrograms per kg per minute), dopamine acts mainly on:",["Dopamine D1 receptors causing renal vasodilatation","Beta-1 receptors","Alpha-1 receptors","Beta-2 receptors"],"Higher doses stimulate beta-1 receptors and very high doses stimulate alpha-1 receptors."],["q-fcps-pha4-20","Which beta-blocker has intrinsic sympathomimetic activity?",["Pindolol","Propranolol","Atenolol","Metoprolol"],"Pindolol and acebutolol are partial agonists, which gives less bradycardia."],["q-fcps-pha4-21","Which drug is a combined alpha and beta blocker used in heart failure and hypertension?",["Carvedilol","Atenolol","Prazosin","Bisoprolol"],"Carvedilol blocks beta-1, beta-2 and alpha-1 receptors and improves survival in heart failure."],["q-fcps-pha4-22","Nitrates relieve angina mainly by:",["Venodilatation that reduces preload","Increasing heart rate","Blocking calcium channels","Increasing contractility"],"Nitric oxide release raises cGMP and relaxes smooth muscle, so venous return and myocardial oxygen demand fall."],["q-fcps-pha4-23","Which is a common adverse effect of nifedipine?",["Reflex tachycardia and ankle oedema","Bradycardia","Constipation","AV block"],"Dihydropyridines are vascular selective and cause flushing, headache and peripheral oedema. Verapamil causes constipation."],["q-fcps-pha4-24","Hydralazine is associated with:",["Drug-induced lupus","Hyperkalaemia","Cough","Gout"],"Slow acetylators are at higher risk of lupus-like syndrome with antihistone antibodies."],["q-fcps-pha4-25","ACE inhibitors are contraindicated in:",["Bilateral renal artery stenosis","Heart failure","Diabetic nephropathy","Post-myocardial infarction"],"Loss of angiotensin II-mediated efferent constriction in a stenosed kidney can cause acute renal failure."],["q-fcps-pha4-26","Which class of antiarrhythmic is lidocaine?",["Class IB","Class IA","Class IC","Class III"],"Lidocaine blocks sodium channels in ischaemic or depolarised tissue and shortens the action potential."],["q-fcps-pha4-27","Flecainide is contraindicated after myocardial infarction because it:",["Increases mortality (proarrhythmic) in the CAST trial","Causes heart block only","Prolongs QT","Causes pulmonary fibrosis"],"Class IC drugs are pro-arrhythmic in structural heart disease."],["q-fcps-pha4-28","Which antiarrhythmic prolongs the QT interval and can cause torsades de pointes?",["Sotalol","Lidocaine","Verapamil","Adenosine"],"Sotalol is a class III agent with beta-blocking properties. Other QT-prolonging drugs include macrolides and many antipsychotics."],["q-fcps-pha4-29","The treatment of torsades de pointes is:",["Intravenous magnesium sulphate","Amiodarone","Digoxin","Procainamide"],"Magnesium stabilises the membrane, and the offending drug is stopped and potassium corrected."],["q-fcps-pha4-30","Which drug improves survival in heart failure with reduced ejection fraction by blocking aldosterone receptors?",["Spironolactone","Furosemide","Digoxin","Amlodipine"],"Spironolactone and eplerenone reduce mortality, but monitor for hyperkalaemia and gynaecomastia."],["q-fcps-pha4-31","Ivabradine reduces heart rate by inhibiting:",["The funny current (If) in the sinoatrial node","L-type calcium channels","Beta-1 receptors","The sodium-potassium pump"],"It lowers rate without negative inotropy and can cause visual phosphenes."],["q-fcps-pha4-32","Statin-induced myopathy is more likely when the statin is combined with:",["Fibrates","Ezetimibe","Aspirin","Metformin"],"Gemfibrozil raises statin levels by inhibiting glucuronidation, and the risk of rhabdomyolysis increases."],["q-fcps-pha4-33","Ezetimibe lowers cholesterol by:",["Inhibiting NPC1L1-mediated intestinal cholesterol absorption","Inhibiting HMG-CoA reductase","Binding bile acids","Activating PPAR-alpha"],"It reduces cholesterol absorption and is added when statins alone are insufficient."],["q-fcps-pha4-34","Which lipid-lowering drug causes flushing mediated by prostaglandins?",["Nicotinic acid (niacin)","Cholestyramine","Fenofibrate","Atorvastatin"],"Aspirin taken before the dose reduces flushing."],["q-fcps-pha4-35","Reversal of warfarin in a patient with life-threatening bleeding requires:",["Vitamin K and prothrombin complex concentrate","Protamine sulphate","Tranexamic acid alone","Idarucizumab"],"Vitamin K restores synthesis, but its effect takes hours, so PCC gives immediate reversal."],["q-fcps-pha4-36","Idarucizumab reverses the effect of:",["Dabigatran","Rivaroxaban","Heparin","Warfarin"],"It is a monoclonal antibody fragment that binds dabigatran. Andexanet alfa reverses factor Xa inhibitors."],["q-fcps-pha4-37","Protamine sulphate neutralises:",["Heparin","Warfarin","Alteplase","Clopidogrel"],"The positively charged protein binds negatively charged heparin."],["q-fcps-pha4-38","Alteplase is:",["A recombinant tissue plasminogen activator","A factor Xa inhibitor","A glycoprotein IIb/IIIa blocker","A vitamin K antagonist"],"It converts plasminogen to plasmin and is used within the time window in ischaemic stroke and myocardial infarction."],["q-fcps-pha4-39","Tranexamic acid acts by:",["Inhibiting plasminogen activation","Activating factor VII","Inhibiting thrombin","Blocking P2Y12"],"It is a lysine analogue that blocks fibrin binding of plasminogen and is used for menorrhagia and trauma."],["q-fcps-pha4-40","Loop diuretics commonly cause:",["Hypokalaemia and ototoxicity","Hyperkalaemia","Hypercalcaemia","Hypouricaemia"],"Furosemide wastes potassium and magnesium and can cause hyperuricaemia and, at high doses, ototoxicity. It increases calcium excretion."],["q-fcps-pha4-41","Thiazide diuretics:",["Reduce urinary calcium excretion","Increase calcium excretion","Cause hyperkalaemia","Are effective at a GFR below 10"],"They are used in idiopathic hypercalciuria with stones and can cause hypercalcaemia, hyponatraemia and hyperglycaemia."],["q-fcps-pha4-42","Amiloride is a diuretic that acts by blocking:",["ENaC in the collecting duct","Na-K-2Cl cotransporter","Aldosterone receptor","Carbonic anhydrase"],"It is potassium-sparing, and lithium-induced nephrogenic diabetes insipidus is treated with it."],["q-fcps-pha4-43","Salmeterol is best described as a:",["Long-acting beta-2 agonist","Short-acting beta-2 agonist","Muscarinic antagonist","Leukotriene antagonist"],"It is used with inhaled corticosteroids for asthma and should not be used alone."],["q-fcps-pha4-44","Montelukast acts by:",["Blocking cysteinyl leukotriene receptors","Inhibiting 5-lipoxygenase","Stabilising mast cells","Inhibiting phosphodiesterase"],"Zileuton inhibits 5-lipoxygenase. Montelukast is useful in aspirin-sensitive asthma and exercise-induced bronchoconstriction."],["q-fcps-pha4-45","Which adverse effect is common with high-dose inhaled corticosteroids?",["Oral candidiasis and hoarseness","Adrenal crisis","Bronchospasm only","Osteoporosis at standard doses"],"Rinsing the mouth and using a spacer reduces local effects."],["q-fcps-pha4-46","Theophylline toxicity can present with:",["Seizures and tachyarrhythmias","Bradycardia","Drowsiness only","Hypokalaemia with constipation only"],"It has a narrow therapeutic index, and its clearance falls with ciprofloxacin, erythromycin, heart failure and cirrhosis."],["q-fcps-pha4-47","Which drug acts as a prostaglandin E1 analogue and protects the gastric mucosa but is contraindicated in pregnancy?",["Misoprostol","Sucralfate","Omeprazole","Ranitidine"],"Misoprostol causes uterine contraction, and its main adverse effect is diarrhoea."],["q-fcps-pha4-48","Sucralfate acts by:",["Forming a protective barrier over the ulcer base in an acid environment","Blocking H2 receptors","Inhibiting the proton pump","Neutralising acid"],"It requires an acidic pH for activation, so it should not be given with antacids, and it may cause constipation."],["q-fcps-pha4-49","Domperidone is preferred to metoclopramide in Parkinson disease because it:",["Does not cross the blood-brain barrier","Is a dopamine agonist","Blocks 5-HT3 receptors","Has no QT effect"],"It is a peripheral D2 antagonist, but it can still prolong the QT interval."],["q-fcps-pha4-50","Loperamide acts by:",["Stimulating mu opioid receptors in the gut to reduce motility","Blocking 5-HT3 receptors","Binding bile acids","Increasing intestinal secretion"],"It has poor central penetration because it is a P-glycoprotein substrate, so it has little abuse potential at normal doses."],["q-fcps-pha4-51","A patient on metformin has a CT with intravenous contrast. Why is metformin withheld?",["Risk of lactic acidosis with acute kidney injury","Risk of hypoglycaemia","Contrast inactivates metformin","Risk of hepatotoxicity"],"Metformin is renally cleared and accumulates if the kidneys are injured."],["q-fcps-pha4-52","SGLT2 inhibitors such as empagliflozin commonly cause:",["Genital mycotic infections and euglycaemic ketoacidosis","Hypoglycaemia in monotherapy","Weight gain","Pancreatitis"],"They cause glycosuria, with benefits for heart failure and chronic kidney disease."],["q-fcps-pha4-53","GLP-1 receptor agonists such as liraglutide cause:",["Weight loss and nausea","Weight gain","Hypoglycaemia as monotherapy","Lactic acidosis"],"They increase glucose-dependent insulin secretion and delay gastric emptying."],["q-fcps-pha4-54","Carbimazole is associated with:",["Agranulocytosis","Hypercalcaemia","Pulmonary fibrosis","Optic neuritis"],"Patients should report sore throat and fever, and propylthiouracil causes hepatotoxicity."],["q-fcps-pha4-55","Desmopressin is used in all EXCEPT:",["SIADH","Central diabetes insipidus","Nocturnal enuresis","Mild haemophilia A"],"It is an ADH analogue, so it would worsen SIADH and cause hyponatraemia."],["q-fcps-pha4-56","Octreotide is a synthetic analogue of:",["Somatostatin","Growth hormone","Vasopressin","Oxytocin"],"It is used in acromegaly, carcinoid syndrome and variceal bleeding."],["q-fcps-pha4-57","Third-generation cephalosporins have:",["Better gram-negative activity and CNS penetration","Better gram-positive activity than first generation","Anaerobic activity","Activity against MRSA"],"Ceftriaxone is used for meningitis and gonorrhoea, but cephalosporins have no activity against enterococci or Listeria."],["q-fcps-pha4-58","Ceftriaxone should be avoided in neonates because it:",["Displaces bilirubin and may precipitate with calcium","Causes grey baby syndrome","Causes tendon rupture","Is nephrotoxic"],"It can cause kernicterus and lethal calcium-ceftriaxone precipitates."],["q-fcps-pha4-59","Which beta-lactam has no cross-reactivity with penicillin allergy and covers gram-negative rods only?",["Aztreonam","Imipenem","Cefazolin","Piperacillin"],"Aztreonam is a monobactam active against aerobic gram-negative bacteria, including Pseudomonas."],["q-fcps-pha4-60","Imipenem is given with cilastatin in order to:",["Inhibit renal dehydropeptidase","Increase absorption","Reduce resistance","Block penicillin-binding proteins"],"Cilastatin prevents renal breakdown, and imipenem lowers the seizure threshold."],["q-fcps-pha4-61","Which antibiotic prolongs the QT interval and is a potent CYP3A4 inhibitor?",["Clarithromycin","Azithromycin","Doxycycline","Amoxicillin"],"Clarithromycin and erythromycin inhibit CYP3A4 and prolong the QT interval, but azithromycin has fewer interactions."],["q-fcps-pha4-62","Clindamycin is most strongly associated with:",["Pseudomembranous colitis","Ototoxicity","Tendon rupture","Red man syndrome"],"Broad disruption of gut flora allows Clostridioides difficile overgrowth."],["q-fcps-pha4-63","Linezolid acts by:",["Inhibiting formation of the 50S initiation complex","Blocking the 30S subunit","Inhibiting cell wall synthesis","Inhibiting DNA gyrase"],"It is active against MRSA and VRE and causes myelosuppression and, with SSRIs, serotonin syndrome."],["q-fcps-pha4-64","Pyrazinamide commonly causes:",["Hyperuricaemia","Optic neuritis","Peripheral neuropathy","Orange urine"],"It inhibits renal urate excretion, and it is hepatotoxic."],["q-fcps-pha4-65","Fluconazole is the drug of choice for:",["Cryptococcal meningitis maintenance and candidiasis","Invasive aspergillosis","Mucormycosis","Dermatophyte nail infection"],"Fluconazole penetrates the CSF well, but it has no activity against moulds."],["q-fcps-pha4-66","The first-line treatment of invasive aspergillosis is:",["Voriconazole","Fluconazole","Nystatin","Terbinafine"],"Voriconazole can cause visual disturbance and hepatotoxicity, and amphotericin B is an alternative."],["q-fcps-pha4-67","Oseltamivir acts by inhibiting:",["Neuraminidase","DNA polymerase","Reverse transcriptase","Protease"],"It prevents viral release and works best when started within 48 hours of symptoms."],["q-fcps-pha4-68","Zidovudine commonly causes:",["Bone marrow suppression with macrocytic anaemia","Pancreatitis","Nephrolithiasis","Hepatic steatosis only"],"It is a nucleoside reverse transcriptase inhibitor, and it is used to prevent mother-to-child transmission."],["q-fcps-pha4-69","Indinavir can cause:",["Nephrolithiasis","Anaemia","Pancreatitis","Peripheral neuropathy"],"Hydration reduces the risk, and protease inhibitors cause lipodystrophy and CYP3A4 inhibition."],["q-fcps-pha4-70","Chloroquine in long-term use can cause:",["Retinopathy","Haemolysis in G6PD deficiency","Hepatitis","Hypoglycaemia only"],"Hydroxychloroquine and chloroquine can cause bull's eye maculopathy and need screening."],["q-fcps-pha4-71","Artesunate is the drug of choice for:",["Severe falciparum malaria","Vivax radical cure","Amoebic liver abscess","Leishmaniasis"],"Intravenous artesunate has better survival than quinine."],["q-fcps-pha4-72","Praziquantel is used for:",["Schistosomiasis and tapeworms","Ascariasis only","Strongyloides only","Amoebiasis"],"It increases calcium influx into the parasite, causing paralysis."],["q-fcps-pha4-73","Ivermectin is the drug of choice for:",["Strongyloidiasis and onchocerciasis","Hydatid disease","Taeniasis","Giardiasis"],"It acts on glutamate-gated chloride channels of nematodes."],["q-fcps-pha4-74","Vincristine characteristically causes:",["Peripheral neuropathy","Myelosuppression as the dose-limiting effect","Cardiotoxicity","Haemorrhagic cystitis"],"It inhibits microtubule polymerisation, and vinblastine causes myelosuppression."],["q-fcps-pha4-75","Cisplatin is associated with:",["Nephrotoxicity, ototoxicity and severe emesis","Pulmonary fibrosis","Cardiomyopathy","Peripheral neuropathy from taxane action"],"Amifostine and hydration reduce renal toxicity."],["q-fcps-pha4-76","Paclitaxel acts by:",["Stabilising microtubules","Inhibiting topoisomerase","Alkylating DNA","Inhibiting dihydrofolate reductase"],"It prevents microtubule depolymerisation, so mitosis is arrested."],["q-fcps-pha4-77","Imatinib is used for:",["Chronic myeloid leukaemia (BCR-ABL tyrosine kinase)","Hairy cell leukaemia","Hodgkin lymphoma","Multiple myeloma"],"It also treats gastrointestinal stromal tumours through KIT inhibition."],["q-fcps-pha4-78","Tamoxifen increases the risk of:",["Endometrial carcinoma","Osteoporosis in postmenopausal women","Breast cancer in the opposite breast","Ovarian cancer"],"It is an oestrogen receptor antagonist in the breast but a partial agonist in the endometrium and bone."],["q-fcps-pha4-79","Tacrolimus acts by:",["Binding FKBP and inhibiting calcineurin","Inhibiting inosine monophosphate dehydrogenase","Inhibiting mTOR","Blocking the IL-2 receptor"],"Its adverse effects include nephrotoxicity, neurotoxicity and diabetes, and mycophenolate inhibits IMPDH."],["q-fcps-pha4-80","Indomethacin is used to close a patent ductus arteriosus because it:",["Inhibits prostaglandin synthesis","Constricts the ductus directly via thromboxane","Blocks calcium channels","Increases oxygen tension"],"Prostaglandin E2 keeps the ductus open, and alprostadil is used to keep it open in duct-dependent defects."],["q-fcps-pha4-81","Celecoxib, compared with non-selective NSAIDs, has:",["Less gastric toxicity but an increased cardiovascular risk","More gastric ulceration","No renal effects","Antiplatelet action"],"COX-2 selectivity spares gastric COX-1 but reduces prostacyclin without reducing thromboxane."],["q-fcps-pha4-82","Colchicine acts in acute gout by:",["Inhibiting microtubule polymerisation and neutrophil migration","Inhibiting xanthine oxidase","Increasing uric acid excretion","Inhibiting COX"],"It commonly causes diarrhoea, and toxicity includes bone marrow suppression."],["q-fcps-pha4-83","Probenecid raises plasma levels of penicillin because it:",["Inhibits renal tubular secretion of organic acids","Inhibits hepatic metabolism","Increases absorption","Binds albumin"],"It is also a uricosuric drug that increases uric acid excretion."],["q-fcps-pha4-84","Hydroxychloroquine and methotrexate are examples of:",["Disease-modifying antirheumatic drugs","NSAIDs","Biologic TNF inhibitors","Corticosteroids"],"DMARDs slow the progression of rheumatoid arthritis, and methotrexate is the anchor drug."],["q-fcps-pha4-85","Before starting infliximab, a patient should be screened for:",["Latent tuberculosis","Glucose-6-phosphate dehydrogenase deficiency","HLA-B27","Thiopurine methyltransferase"],"TNF-alpha is needed to maintain granulomas, so reactivation of tuberculosis is a risk."],["q-fcps-pha4-86","Phenytoin shows zero-order kinetics at higher doses, so:",["A small dose increase can cause a large rise in plasma concentration","The half-life is constant","Dosing is independent of level","Clearance increases"],"Metabolic enzymes become saturated, and toxicity includes nystagmus, ataxia and diplopia."],["q-fcps-pha4-87","Ethosuximide is the first-line drug for:",["Absence seizures","Tonic-clonic seizures","Status epilepticus","Myoclonic seizures"],"It blocks T-type calcium channels in thalamic neurons."],["q-fcps-pha4-88","Lamotrigine requires slow dose titration because of the risk of:",["Stevens-Johnson syndrome","Hepatic failure","Gingival hyperplasia","Pancreatitis"],"The risk of rash is higher with rapid titration and with concurrent valproate."],["q-fcps-pha4-89","Carbamazepine commonly causes:",["Hyponatraemia and enzyme induction","Gingival hyperplasia","Weight gain and tremor","Hirsutism"],"SIADH-like effects are seen, and HLA-B*1502 predisposes to Stevens-Johnson syndrome in some Asian populations."],["q-fcps-pha4-90","Neuroleptic malignant syndrome is treated with:",["Dantrolene and supportive care","Haloperidol","Atropine","Naloxone"],"It presents with hyperthermia, muscle rigidity and autonomic instability, and the antipsychotic is stopped."],["q-fcps-pha4-91","Which antipsychotic is most likely to cause weight gain and metabolic syndrome?",["Olanzapine","Haloperidol","Aripiprazole","Ziprasidone"],"Atypical antipsychotics, especially olanzapine and clozapine, cause weight gain and dyslipidaemia."],["q-fcps-pha4-92","Bupropion is contraindicated in patients with:",["Seizure disorders and bulimia","Smoking","Depression","Obesity"],"It lowers the seizure threshold and is also used for smoking cessation."],["q-fcps-pha4-93","Levodopa is given with carbidopa in order to:",["Inhibit peripheral dopa decarboxylase","Inhibit MAO-B in the brain","Block dopamine receptors","Increase dopamine release"],"Carbidopa does not cross the blood-brain barrier, so more levodopa reaches the brain and nausea is reduced."],["q-fcps-pha4-94","Sumatriptan is contraindicated in:",["Ischaemic heart disease","Asthma","Epilepsy","Peptic ulcer"],"5-HT1B/1D agonists cause coronary vasoconstriction."],["q-fcps-pha4-95","Halothane can cause:",["Fulminant hepatitis","Pulmonary fibrosis","Optic neuritis","Ototoxicity"],"Repeated exposure may cause immune-mediated hepatic necrosis."],["q-fcps-pha4-96","Prolonged nitrous oxide anaesthesia can cause:",["Megaloblastic anaemia by inactivating vitamin B12","Hepatitis","Nephrotoxicity","Malignant hyperthermia"],"It oxidises the cobalt of cobalamin and inhibits methionine synthase."],["q-fcps-pha4-97","Propofol is characterised by:",["Rapid recovery and antiemetic effect","Prolonged recovery with accumulation","Strong analgesia","Adrenocortical suppression"],"It is used for induction and sedation, and its adverse effects are hypotension and injection pain."],["q-fcps-pha4-98","Digoxin-specific antibody fragments (Fab) are used for:",["Life-threatening digoxin toxicity","Warfarin reversal","Heparin overdose","Beta-blocker poisoning"],"They bind digoxin and are given for dangerous arrhythmias or hyperkalaemia."],["q-fcps-pha4-99","Dimercaprol is used as a chelator in poisoning with:",["Arsenic, mercury and lead","Iron","Copper only","Cyanide"],"It is a dithiol chelator given by deep intramuscular injection, and succimer is an oral alternative."],["q-fcps-pha4-100","Activated charcoal is NOT effective for poisoning with:",["Lithium","Paracetamol","Tricyclic antidepressants","Aspirin"],"Charcoal adsorbs most drugs, but it binds poorly to small ionised compounds such as lithium, iron, alcohols and corrosives."],["q-fcps-pha5-01","A drug with a high first-pass metabolism has:",["Low oral bioavailability","High oral bioavailability","Long half-life","Complete absorption into the systemic circulation"],"Examples are glyceryl trinitrate, lidocaine and propranolol, and sublingual or parenteral routes bypass first-pass metabolism."],["q-fcps-pha5-02","Volume of distribution is high for drugs that:",["Are lipophilic and bind to tissues","Are highly bound to plasma proteins","Are highly ionised","Are large polar molecules"],"A large volume of distribution means the drug is mostly outside the plasma, as with chloroquine and digoxin."],["q-fcps-pha5-03","Clearance of a drug is defined as:",["The volume of plasma cleared of the drug per unit time","The amount of drug excreted in urine","Half the volume of distribution","The time for the concentration to fall by half"],"Half-life equals 0.693 times Vd divided by clearance."],["q-fcps-pha5-04","After how many half-lives does a drug given at a constant rate reach about 94% of its steady state?",["4","1","2","10"],"Steady state is reached in about 4 to 5 half-lives, irrespective of the dose."],["q-fcps-pha5-05","A loading dose depends mainly on:",["Volume of distribution","Clearance","Half-life","Bioavailability only"],"The maintenance dose depends on clearance."],["q-fcps-pha5-06","Zero-order kinetics is seen with:",["Phenytoin at high doses, ethanol and aspirin overdose","Most drugs at therapeutic doses","Penicillin","Gentamicin"],"A constant amount rather than a constant fraction of the drug is eliminated per unit time because the enzymes are saturated."],["q-fcps-pha5-07","Weak acids are more readily excreted in the urine when the urine is:",["Alkaline","Acidic","Neutral","Concentrated"],"Urinary alkalinisation with bicarbonate is used in salicylate and phenobarbital poisoning."],["q-fcps-pha5-08","Which is a cytochrome P450 enzyme inducer?",["Rifampicin","Ketoconazole","Cimetidine","Erythromycin"],"Other inducers are phenytoin, carbamazepine, phenobarbital, St John's wort and chronic alcohol use. They may reduce the effect of oral contraceptives and warfarin."],["q-fcps-pha5-09","Which of the following is a cytochrome P450 inhibitor?",["Ciprofloxacin","Carbamazepine","Griseofulvin","Rifampicin"],"Other inhibitors are macrolides, azoles, cimetidine, grapefruit juice and valproate."],["q-fcps-pha5-10","Which of these drugs is a prodrug that needs activation by the liver?",["Clopidogrel","Morphine","Lisinopril","Propranolol"],"Enalapril, codeine and cyclophosphamide are also prodrugs, and lisinopril is an active drug."],["q-fcps-pha5-11","Slow acetylators have an increased risk of:",["Isoniazid-induced neuropathy and drug-induced lupus","Isoniazid inefficacy","Warfarin resistance","Malignant hyperthermia"],"Hydralazine and procainamide also cause drug-induced lupus, with anti-histone antibodies."],["q-fcps-pha5-12","Succinylcholine apnoea is caused by:",["Pseudocholinesterase deficiency","G6PD deficiency","Acetylator status","CYP2D6 deficiency"],"Prolonged paralysis occurs because the drug is not broken down."],["q-fcps-pha5-13","Primaquine causes haemolysis in patients with:",["G6PD deficiency","Pyruvate kinase deficiency","Hereditary spherocytosis","Sickle cell disease"],"Dapsone, sulphonamides, nitrofurantoin and rasburicase are other triggers."],["q-fcps-pha5-14","Which receptor type is a ligand-gated ion channel?",["Nicotinic acetylcholine receptor","Muscarinic M1 receptor","Beta-1 adrenergic receptor","Insulin receptor"],"Muscarinic and adrenergic receptors are G protein-coupled, and the insulin receptor is a tyrosine kinase receptor."],["q-fcps-pha5-15","An antagonist that binds to the same site as the agonist and whose effect can be overcome by increasing agonist concentration is:",["Competitive antagonist","Non-competitive antagonist","Partial agonist","Inverse agonist"],"A competitive antagonist shifts the dose-response curve to the right without changing the maximum."],["q-fcps-pha5-16","Potency of a drug is determined by:",["The dose needed to produce a given effect","The maximum effect","Duration of action","Therapeutic index"],"Efficacy is the maximum effect, and a drug can be more potent but less efficacious."],["q-fcps-pha5-17","Therapeutic index is:",["LD50 divided by ED50","ED50 divided by LD50","Half-life divided by clearance","Cmax divided by Cmin"],"A narrow therapeutic index applies to digoxin, lithium, warfarin, phenytoin and theophylline."],["q-fcps-pha5-18","Tachyphylaxis refers to:",["A rapidly developing tolerance after repeated doses","An allergic reaction","A genetic variation in response","An unexpected effect at the first dose"],"Ephedrine and nitrates are examples."],["q-fcps-pha5-19","Which drug is a direct-acting cholinergic agonist used in glaucoma and xerostomia?",["Pilocarpine","Atropine","Neostigmine","Physostigmine"],"Pilocarpine causes miosis and contraction of the ciliary muscle, which opens the trabecular meshwork."],["q-fcps-pha5-20","Which drug is used to treat myasthenia gravis and also reverses non-depolarising neuromuscular blockade?",["Neostigmine","Physostigmine","Edrophonium for long term","Atropine"],"Physostigmine crosses the blood-brain barrier and is used for anticholinergic poisoning."],["q-fcps-pha5-21","Organophosphate poisoning is treated with atropine and:",["Pralidoxime","Flumazenil","Naloxone","Neostigmine"],"Pralidoxime reactivates cholinesterase if given early before ageing of the enzyme-inhibitor complex."],["q-fcps-pha5-22","Which antimuscarinic is used for bronchospasm in COPD and has a long duration?",["Tiotropium","Salbutamol","Theophylline","Montelukast"],"Ipratropium is a shorter-acting antimuscarinic."],["q-fcps-pha5-23","Which beta-blocker is both cardioselective and has no intrinsic sympathomimetic activity?",["Metoprolol","Pindolol","Propranolol","Carvedilol"],"Pindolol has intrinsic sympathomimetic activity, and carvedilol also blocks alpha-1 receptors."],["q-fcps-pha5-24","Which drug is the first-line treatment for anaphylaxis?",["Intramuscular adrenaline","Hydrocortisone","Chlorpheniramine","Salbutamol"],"Adrenaline 0.5 mg of 1 in 1000 is given into the anterolateral thigh in adults."],["q-fcps-pha5-25","Which drug is a selective alpha-1 blocker used in benign prostatic hyperplasia?",["Tamsulosin","Phenoxybenzamine","Clonidine","Prazosin only for hypertension"],"Alpha-1A selectivity reduces hypotension, and intraoperative floppy iris syndrome is a concern during cataract surgery."],["q-fcps-pha5-26","Phenoxybenzamine is used for:",["Pheochromocytoma","Hypertension in pregnancy","Asthma","Myasthenia gravis"],"It is an irreversible non-selective alpha blocker, and it must be started before a beta blocker."],["q-fcps-pha5-27","Clonidine lowers blood pressure by:",["Stimulating central alpha-2 receptors","Blocking beta receptors","Blocking calcium channels","Inhibiting ACE"],"Abrupt withdrawal causes rebound hypertension."],["q-fcps-pha5-28","Methyldopa is preferred for hypertension in:",["Pregnancy","Asthma","Diabetes","Gout"],"It is converted to alpha-methylnorepinephrine and may cause a positive Coombs test."],["q-fcps-pha5-29","A dry cough with ACE inhibitors is due to accumulation of:",["Bradykinin","Angiotensin II","Histamine","Substance P only"],"Angioedema is also due to bradykinin, and it does not occur with ARBs at the same frequency."],["q-fcps-pha5-30","Which diuretic acts on the thick ascending limb of the loop of Henle?",["Furosemide","Hydrochlorothiazide","Spironolactone","Acetazolamide"],"It inhibits the Na+/K+/2Cl- cotransporter, and ototoxicity and hypokalaemia are adverse effects."],["q-fcps-pha5-31","Thiazide diuretics cause all of the following EXCEPT:",["Hypercalciuria","Hyponatraemia","Hyperuricaemia","Hyperglycaemia"],"They reduce calcium excretion, and so they are used for calcium stones."],["q-fcps-pha5-32","Which diuretic causes hyperkalaemia?",["Spironolactone","Furosemide","Indapamide","Mannitol"],"Gynaecomastia is an additional adverse effect of spironolactone and is not seen with eplerenone."],["q-fcps-pha5-33","Mannitol is used to reduce:",["Raised intracranial pressure","Hypertension","Heart failure","Oedema of cirrhosis"],"It is an osmotic diuretic that is contraindicated in anuria and pulmonary oedema."],["q-fcps-pha5-34","Digoxin toxicity is increased by:",["Hypokalaemia","Hyperkalaemia","Hypernatraemia","Hypomagnesaemia only"],"Symptoms include nausea, visual disturbance with yellow-green vision and arrhythmias, and digoxin-specific antibody fragments are the antidote."],["q-fcps-pha5-35","Which antiarrhythmic is the drug of choice for acute termination of supraventricular tachycardia?",["Adenosine","Amiodarone","Verapamil first line","Lidocaine"],"Adenosine has a half-life of seconds, so it is given as a rapid bolus; theophylline antagonises it."],["q-fcps-pha5-36","Amiodarone adverse effects include all of the following EXCEPT:",["Hypoglycaemia","Pulmonary fibrosis","Thyroid dysfunction","Corneal microdeposits"],"Blue-grey skin discolouration, photosensitivity and hepatotoxicity also occur."],["q-fcps-pha5-37","Class IC antiarrhythmics such as flecainide are contraindicated after:",["Myocardial infarction","Asthma","Hypothyroidism","Gout"],"The CAST trial showed increased mortality."],["q-fcps-pha5-38","Which statin adverse effect requires checking creatine kinase?",["Myopathy and rhabdomyolysis","Hyperkalaemia","Pancreatitis","Cataract only"],"The risk is increased by interaction with fibrates, macrolides and azoles."],["q-fcps-pha5-39","Which antiplatelet drug irreversibly inhibits COX-1?",["Aspirin","Clopidogrel","Ticagrelor","Abciximab"],"Clopidogrel irreversibly blocks the P2Y12 receptor, and ticagrelor blocks it reversibly."],["q-fcps-pha5-40","Warfarin is monitored using:",["INR","aPTT","Anti-Xa","Bleeding time"],"Heparin is monitored using aPTT (unfractionated) and low molecular weight heparin using anti-Xa if needed."],["q-fcps-pha5-41","The antidote for life-threatening warfarin bleeding is:",["Prothrombin complex concentrate with vitamin K","Protamine","Vitamin C","Tranexamic acid alone"],"Fresh frozen plasma can be used if the concentrate is unavailable."],["q-fcps-pha5-42","Protamine sulphate reverses:",["Unfractionated heparin","Warfarin","Dabigatran","Rivaroxaban"],"Idarucizumab reverses dabigatran and andexanet alfa reverses factor Xa inhibitors."],["q-fcps-pha5-43","Alteplase is used within what time window for ischaemic stroke?",["4.5 hours","12 hours","24 hours","48 hours"],"It converts plasminogen to plasmin, and intracranial haemorrhage is the main risk."],["q-fcps-pha5-44","Which drug is a sulphonylurea that may cause prolonged hypoglycaemia in the elderly?",["Glibenclamide","Metformin","Pioglitazone","Sitagliptin"],"Sulphonylureas close ATP-sensitive potassium channels in beta cells."],["q-fcps-pha5-45","Metformin is contraindicated in:",["Severe renal impairment because of lactic acidosis risk","Obesity","Polycystic ovary syndrome","Hypertension"],"It decreases hepatic gluconeogenesis and increases insulin sensitivity, and it does not cause hypoglycaemia by itself."],["q-fcps-pha5-46","Which class of antidiabetic agents causes genital mycotic infections and euglycaemic ketoacidosis?",["SGLT2 inhibitors","DPP-4 inhibitors","Sulphonylureas","Thiazolidinediones"],"Empagliflozin and dapagliflozin also benefit heart failure and chronic kidney disease."],["q-fcps-pha5-47","Pioglitazone acts through:",["PPAR-gamma","PPAR-alpha","GLP-1 receptors","Sulphonylurea receptors"],"It may cause fluid retention, heart failure and bone fractures."],["q-fcps-pha5-48","Which drug is the treatment of choice for thyroid storm to reduce peripheral conversion of T4 to T3?",["Propylthiouracil","Carbimazole","Radioactive iodine","Levothyroxine"],"Beta-blockers control the adrenergic symptoms and PTU is preferred in the first trimester of pregnancy."],["q-fcps-pha5-49","Which is the most serious adverse effect of carbimazole and PTU?",["Agranulocytosis","Hypertension","Hyperkalaemia","Pulmonary fibrosis"],"Patients should report fever or sore throat."],["q-fcps-pha5-50","Glucocorticoid long-term use causes all of the following EXCEPT:",["Hypoglycaemia","Osteoporosis","Cataract","Adrenal suppression"],"Hyperglycaemia, central obesity and skin thinning also occur."],["q-fcps-pha5-51","Which corticosteroid has the highest mineralocorticoid activity?",["Fludrocortisone","Dexamethasone","Prednisolone","Methylprednisolone"],"Dexamethasone has the longest duration and is essentially devoid of mineralocorticoid action."],["q-fcps-pha5-52","The progesterone receptor modulator used for medical termination of early pregnancy is:",["Mifepristone","Clomiphene","Letrozole","Tamoxifen"],"It is used with misoprostol, a prostaglandin E1 analogue."],["q-fcps-pha5-53","Clomiphene citrate induces ovulation by:",["Blocking oestrogen receptors in the hypothalamus","Stimulating FSH receptors","Inhibiting aromatase","Acting as a GnRH agonist"],"The loss of negative feedback increases GnRH and gonadotropins, and multiple pregnancy is a risk."],["q-fcps-pha5-54","Which drug is used to suppress lactation?",["Cabergoline","Metoclopramide","Oxytocin","Domperidone"],"Dopamine agonists inhibit prolactin release."],["q-fcps-pha5-55","Oxytocin used for postpartum haemorrhage can cause:",["Water intoxication","Hypertension only","Hypernatraemia","Hypocalcaemia"],"It has a mild antidiuretic effect."],["q-fcps-pha5-56","Which drug is a tocolytic that blocks calcium channels?",["Nifedipine","Ritodrine","Atosiban","Magnesium sulphate"],"Atosiban is an oxytocin receptor antagonist."],["q-fcps-pha5-57","Magnesium sulphate toxicity is first detected clinically by:",["Loss of patellar reflex","Respiratory depression","Cardiac arrest","Hypertension"],"Calcium gluconate is the antidote."],["q-fcps-pha5-58","Which opioid is a prodrug with a weak action, converted by CYP2D6?",["Codeine","Morphine","Fentanyl","Methadone"],"Ultra-rapid metabolisers may have respiratory depression."],["q-fcps-pha5-59","Which opioid antagonist is given for opioid overdose?",["Naloxone","Naltrexone for acute reversal","Flumazenil","Atropine"],"Naloxone has a short duration, so repeat doses or infusion may be needed."],["q-fcps-pha5-60","Pethidine should be avoided in patients taking MAO inhibitors because of:",["Serotonin syndrome","Hypoglycaemia","Hypertensive crisis only","Bradycardia only"],"Pethidine also has an active metabolite, norpethidine, which causes seizures."],["q-fcps-pha5-61","Which drug is the antidote for benzodiazepine overdose?",["Flumazenil","Naloxone","Physostigmine","Acetylcysteine"],"It may precipitate seizures in chronic benzodiazepine users."],["q-fcps-pha5-62","Which drug is the antidote for paracetamol overdose?",["N-acetylcysteine","Naloxone","Flumazenil","Fomepizole"],"It replenishes glutathione and is most effective within 8 hours."],["q-fcps-pha5-63","Which is the antidote for methanol or ethylene glycol poisoning?",["Fomepizole","Atropine","Methylene blue","Dimercaprol"],"It inhibits alcohol dehydrogenase, and ethanol can be used if it is unavailable."],["q-fcps-pha5-64","Methylene blue is used for:",["Methaemoglobinaemia","Cyanide poisoning","Lead poisoning","Iron overload"],"It reduces methaemoglobin to haemoglobin, but it is ineffective in G6PD deficiency."],["q-fcps-pha5-65","Which chelating agent is used for lead poisoning in children with encephalopathy?",["Sodium calcium edetate with dimercaprol","Desferrioxamine","Penicillamine for acute poisoning","Hydroxocobalamin"],"Succimer is the oral agent for milder poisoning."],["q-fcps-pha5-66","Desferrioxamine is used for:",["Iron poisoning","Copper poisoning","Arsenic poisoning","Mercury poisoning"],"It may colour the urine vin-rosé."],["q-fcps-pha5-67","Hydroxocobalamin is used for:",["Cyanide poisoning","Carbon monoxide poisoning","Organophosphate poisoning","Lead poisoning"],"Sodium nitrite and sodium thiosulphate are alternatives."],["q-fcps-pha5-68","Which anticonvulsant is the drug of choice for absence seizures?",["Ethosuximide or sodium valproate","Carbamazepine","Phenytoin","Gabapentin"],"Carbamazepine and phenytoin may aggravate absence seizures."],["q-fcps-pha5-69","Which antiepileptic causes gingival hyperplasia and hirsutism?",["Phenytoin","Valproate","Lamotrigine","Levetiracetam"],"Fetal hydantoin syndrome and megaloblastic anaemia are also seen with phenytoin."],["q-fcps-pha5-70","Valproate is associated with:",["Neural tube defects in the fetus and hepatotoxicity","Gingival hyperplasia","Aplastic anaemia as the main effect","Hyponatraemia as the main effect"],"Carbamazepine causes hyponatraemia (SIADH) and Stevens-Johnson syndrome in patients with HLA-B*1502."],["q-fcps-pha5-71","Which drug is the first-line treatment of status epilepticus?",["Intravenous lorazepam","Phenytoin","Valproate","Carbamazepine"],"Phenytoin or levetiracetam is used if seizures continue."],["q-fcps-pha5-72","The mechanism of action of levodopa with carbidopa is:",["Carbidopa prevents peripheral conversion of levodopa to dopamine","Carbidopa inhibits MAO-B","Carbidopa stimulates dopamine receptors","Carbidopa blocks COMT centrally"],"Carbidopa does not cross the blood-brain barrier."],["q-fcps-pha5-73","Which dopamine agonist is ergot-derived and may cause pulmonary fibrosis?",["Bromocriptine","Pramipexole","Ropinirole","Selegiline"],"Selegiline is an MAO-B inhibitor."],["q-fcps-pha5-74","Which antipsychotic is most associated with agranulocytosis and needs blood monitoring?",["Clozapine","Haloperidol","Risperidone","Aripiprazole"],"It is used in treatment-resistant schizophrenia and also causes myocarditis and seizures."],["q-fcps-pha5-75","Lithium toxicity is increased by:",["Thiazide diuretics and NSAIDs","Caffeine","Aminophylline","Sodium loading"],"Lithium has a narrow therapeutic index, and it causes tremor, nephrogenic diabetes insipidus and hypothyroidism."],["q-fcps-pha5-76","Which antidepressant class is associated with hypertensive crisis after eating tyramine-rich foods?",["MAO inhibitors","SSRIs","Tricyclics","Mirtazapine"],"Cheese, red wine and broad beans contain tyramine."],["q-fcps-pha5-77","Which drug is used to treat tricyclic antidepressant-induced cardiac toxicity?",["Sodium bicarbonate","Flumazenil","Atropine","Digoxin"],"Sodium channel blockade widens the QRS, and alkalinisation helps."],["q-fcps-pha5-78","Which general anaesthetic is associated with malignant hyperthermia?",["Halothane and succinylcholine","Propofol","Ketamine","Nitrous oxide only"],"Dantrolene blocks ryanodine receptor calcium release."],["q-fcps-pha5-79","Which intravenous anaesthetic causes dissociative anaesthesia and increases blood pressure?",["Ketamine","Propofol","Thiopentone","Etomidate"],"It is useful in asthma and hypovolaemic shock, but emergence delirium can occur."],["q-fcps-pha5-80","Which local anaesthetic is most cardiotoxic?",["Bupivacaine","Lidocaine","Procaine","Prilocaine"],"Lipid emulsion is used to treat systemic local anaesthetic toxicity."],["q-fcps-pha5-81","Which local anaesthetic can cause methaemoglobinaemia?",["Prilocaine","Bupivacaine","Ropivacaine","Procaine"],"Benzocaine is another cause."],["q-fcps-pha5-82","Local anaesthetics block:",["Voltage-gated sodium channels","Potassium channels","Calcium channels","Chloride channels"],"Local anaesthetics are less effective in infected tissue because the acid environment reduces the unionised fraction."],["q-fcps-pha5-83","Which neuromuscular blocker is metabolised by Hofmann elimination?",["Atracurium","Vecuronium","Pancuronium","Rocuronium"],"It is suitable for patients with renal and hepatic failure, and laudanosine may cause seizures."],["q-fcps-pha5-84","Penicillins act by:",["Inhibiting transpeptidase and cell wall synthesis","Inhibiting protein synthesis","Inhibiting DNA gyrase","Inhibiting folate synthesis"],"Beta-lactamase inhibitors such as clavulanic acid extend their spectrum."],["q-fcps-pha5-85","Which antibiotic is first-line for syphilis?",["Benzathine penicillin","Ciprofloxacin","Gentamicin","Chloramphenicol"],"The Jarisch-Herxheimer reaction may follow the first dose."],["q-fcps-pha5-86","Which cephalosporin has good penetration of the CSF and is used for meningitis?",["Ceftriaxone","Cefazolin","Cefalexin","Cefuroxime for all cases"],"Ceftriaxone can cause biliary sludging and should be avoided in neonates with hyperbilirubinaemia."],["q-fcps-pha5-87","Which carbapenem is not inactivated by renal dehydropeptidase and does not need cilastatin?",["Meropenem","Imipenem","Penicillin","Cefazolin"],"Imipenem is given with cilastatin and may lower the seizure threshold."],["q-fcps-pha5-88","Aminoglycosides act by:",["Binding to the 30S ribosomal subunit","Binding to the 50S subunit","Inhibiting cell wall synthesis","Inhibiting RNA polymerase"],"Adverse effects are nephrotoxicity, ototoxicity and neuromuscular blockade."],["q-fcps-pha5-89","Which antibiotic causes tendon rupture and cartilage damage in children?",["Ciprofloxacin","Doxycycline","Gentamicin","Azithromycin"],"Fluoroquinolones inhibit DNA gyrase and topoisomerase IV."],["q-fcps-pha5-90","Tetracyclines are contraindicated in pregnancy and children below 8 years because of:",["Tooth discolouration and bone growth effects","Hearing loss","Grey baby syndrome","Kernicterus"],"They bind calcium, and so absorption is reduced by milk and antacids."],["q-fcps-pha5-91","Which macrolide causes the most inhibition of cytochrome P450 enzymes?",["Erythromycin or clarithromycin","Azithromycin","Roxithromycin only","All have the same effect"],"Azithromycin has minimal interaction and a long half-life."],["q-fcps-pha5-92","Chloramphenicol causes dose-related bone marrow suppression and:",["Grey baby syndrome in neonates","Ototoxicity","Tendon rupture","Red man syndrome"],"Aplastic anaemia is an idiosyncratic reaction."],["q-fcps-pha5-93","Vancomycin infusion reaction (red man syndrome) is due to:",["Histamine release","IgE-mediated anaphylaxis","Immune complex formation","Direct nephrotoxicity"],"Slowing the infusion rate and giving antihistamines prevent it."],["q-fcps-pha5-94","Which drug is used for Clostridioides difficile infection?",["Oral vancomycin or fidaxomicin","Intravenous vancomycin","Ceftriaxone","Ciprofloxacin"],"Oral vancomycin is not absorbed, so it acts locally in the gut."],["q-fcps-pha5-95","Metronidazole acts against:",["Anaerobes and protozoa","Aerobic gram-positive cocci","Fungi","Viruses"],"A disulfiram-like reaction can occur with alcohol."],["q-fcps-pha5-96","Which antitubercular drug causes optic neuritis?",["Ethambutol","Isoniazid","Pyrazinamide","Rifampicin"],"Colour vision should be tested, and the drug is dose-adjusted in renal failure."],["q-fcps-pha5-97","Isoniazid neuropathy is prevented by:",["Pyridoxine","Thiamine","Folic acid","Vitamin C"],"Isoniazid is hepatotoxic and causes pyridoxine deficiency."],["q-fcps-pha5-98","Which antitubercular drug causes hyperuricaemia?",["Pyrazinamide","Rifampicin","Isoniazid","Streptomycin"],"It also causes hepatotoxicity."],["q-fcps-pha5-99","Rifampicin colours body fluids:",["Orange-red","Blue","Green","Black"],"It also induces liver enzymes, and so it reduces the effect of many drugs."],["q-fcps-pha5-100","Amphotericin B is notable for adverse effects including:",["Nephrotoxicity with hypokalaemia","Gynaecomastia","Hepatitis only","Ototoxicity"],"The liposomal form is less nephrotoxic."],["q-fcps-pha5-101","Which antifungal inhibits ergosterol synthesis by blocking 14-alpha demethylase?",["Fluconazole","Terbinafine","Caspofungin","Nystatin"],"Terbinafine inhibits squalene epoxidase, and caspofungin inhibits beta-glucan synthesis."],["q-fcps-pha5-102","Which drug is used for the treatment of chloroquine-resistant severe falciparum malaria?",["Intravenous artesunate","Chloroquine","Primaquine","Proguanil"],"Primaquine is used to eradicate the liver hypnozoites of P. vivax and P. ovale."],["q-fcps-pha5-103","Which antiviral is used for herpes simplex encephalitis?",["Aciclovir","Oseltamivir","Ribavirin","Zidovudine"],"It is activated by viral thymidine kinase, and crystal nephropathy is a risk with rapid infusion."],["q-fcps-pha5-104","Zidovudine causes:",["Bone marrow suppression with anaemia","Pancreatitis as main effect","Nephrolithiasis","Hyperbilirubinaemia as main effect"],"It is a nucleoside reverse transcriptase inhibitor, and it is used to prevent vertical transmission of HIV."],["q-fcps-pha5-105","Methotrexate toxicity is reduced by:",["Folinic acid (leucovorin)","Folic acid","Vitamin B12","Vitamin K"],"Methotrexate inhibits dihydrofolate reductase."],["q-fcps-pha5-106","Doxorubicin has a dose-limiting toxicity of:",["Cardiomyopathy","Pulmonary fibrosis","Peripheral neuropathy","Haemorrhagic cystitis"],"Bleomycin causes pulmonary fibrosis, vincristine neuropathy and cyclophosphamide haemorrhagic cystitis."],["q-fcps-pha5-107","Mesna is given with cyclophosphamide to prevent:",["Haemorrhagic cystitis","Cardiotoxicity","Neuropathy","Mucositis"],"It binds the toxic metabolite acrolein in the urine."],["q-fcps-pha5-108","Cisplatin is characteristically associated with:",["Nephrotoxicity and ototoxicity","Pulmonary fibrosis","Cardiotoxicity","Peripheral neuropathy only"],"Hydration and amifostine reduce nephrotoxicity, and severe emesis is common."],["q-fcps-pha5-109","Vincristine acts by:",["Inhibiting microtubule polymerisation","Stabilising microtubules","Inhibiting topoisomerase II","Alkylating DNA"],"Paclitaxel stabilises microtubules, and peripheral neuropathy is a feature of both."],["q-fcps-pha5-110","Tamoxifen has an adverse effect of:",["Endometrial cancer and thromboembolism","Osteoporosis","Hypotension","Hypoglycaemia"],"It is an antagonist at the breast and an agonist in the endometrium and bone."],["q-fcps-pha5-111","Which drug is a monoclonal antibody against CD20?",["Rituximab","Trastuzumab","Infliximab","Bevacizumab"],"Infliximab blocks TNF-alpha, and screening for tuberculosis is needed before use."],["q-fcps-pha5-112","Ciclosporin acts by:",["Inhibiting calcineurin and so IL-2 production","Inhibiting mTOR","Inhibiting purine synthesis","Blocking IL-2 receptor"],"Nephrotoxicity, hypertension, hirsutism and gingival hyperplasia are adverse effects."],["q-fcps-pha5-113","Azathioprine toxicity is increased by:",["Allopurinol","Rifampicin","Phenytoin","Spironolactone"],"Xanthine oxidase inhibition reduces its breakdown, so the dose should be reduced."],["q-fcps-pha5-114","Which antiemetic acts as a 5-HT3 antagonist?",["Ondansetron","Metoclopramide","Domperidone","Cyclizine"],"QT prolongation and constipation are adverse effects."],["q-fcps-pha5-115","Which drug is a proton pump inhibitor?",["Omeprazole","Ranitidine","Sucralfate","Misoprostol"],"Long-term use is associated with hypomagnesaemia, B12 deficiency and fractures."],["q-fcps-pha5-116","Misoprostol is contraindicated in pregnancy because it:",["Causes uterine contractions","Is teratogenic via folate","Causes fetal bradycardia","Causes oligohydramnios"],"It is a prostaglandin E1 analogue used for NSAID-induced ulcer prevention."],["q-fcps-pha5-117","Which laxative is an osmotic agent used in hepatic encephalopathy?",["Lactulose","Senna","Bisacodyl","Docusate"],"It acidifies the colon and traps ammonia as ammonium."],["q-fcps-pha5-118","Salbutamol commonly causes:",["Tremor and hypokalaemia","Bradycardia","Hypertension only","Drowsiness"],"Beta-2 stimulation drives potassium into cells."],["q-fcps-pha5-119","Which drug used in asthma is a leukotriene receptor antagonist?",["Montelukast","Zileuton","Theophylline","Cromolyn"],"Zileuton is a 5-lipoxygenase inhibitor."],["q-fcps-pha5-120","Theophylline toxicity is increased by:",["Ciprofloxacin and cimetidine","Smoking","Rifampicin","Phenytoin"],"It has a narrow therapeutic index and causes seizures and arrhythmias."],["q-fcps-pha5-121","Which drug is used to treat gout acutely and acts by inhibiting microtubule polymerisation of neutrophils?",["Colchicine","Allopurinol","Febuxostat","Probenecid"],"Diarrhoea is the commonest adverse effect."],["q-fcps-pha5-122","Aspirin overdose causes initially:",["Respiratory alkalosis followed by metabolic acidosis","Metabolic alkalosis","Respiratory acidosis","Hypoglycaemia only"],"Tinnitus is an early feature, and urinary alkalinisation enhances excretion."],["q-fcps-pha5-123","Which NSAID is selective for COX-2?",["Celecoxib","Ibuprofen","Diclofenac","Indomethacin"],"It has a lower gastrointestinal risk but has cardiovascular risk."],["q-fcps-pha5-124","Which NSAID is used to close a patent ductus arteriosus?",["Indomethacin or ibuprofen","Paracetamol only for closure","Prostaglandin E1","Aspirin"],"Prostaglandin E1 (alprostadil) keeps the ductus open in duct-dependent lesions."],["q-fcps-pha5-125","Hydroxychloroquine may cause:",["Retinopathy","Hepatic fibrosis","Pulmonary fibrosis","Ototoxicity"],"Regular eye screening is needed for long-term users."],["q-fcps-pha5-126","Which disease-modifying drug for rheumatoid arthritis is the first-line choice?",["Methotrexate","Gold","Leflunomide as first line","Penicillamine"],"Folic acid supplements reduce its adverse effects."],["q-fcps-pha6-01","Which route of administration avoids first-pass hepatic metabolism?",["Sublingual","Oral","Rectal (upper)","Enteral via gastric tube"],"Veins of the lower rectum drain into the systemic circulation, but the upper rectum drains through the portal vein.",{"m":"Veins draining the mouth floor go to the superior vena cava, so the drug reaches the systemic circulation without passing through the portal vein and liver.","w":["Swallowed drugs are absorbed into the portal vein and metabolised by hepatic enzymes before reaching the circulation.","Absorbed from the upper rectum through the superior rectal vein into the portal system, so first pass still occurs.","Absorption is still by the gut and portal vein, so hepatic first-pass metabolism occurs."]}],["q-fcps-pha6-02","A drug highly bound to plasma proteins is displaced by another drug, which results in:",["Increase in free drug and effect","Decrease in free drug","No change","Decrease in half-life only"],"Warfarin is displaced by sulphonamides and NSAIDs.",{"m":"Only unbound drug is active and can be metabolised or excreted; displacement raises the free fraction transiently, and the effect rises until the extra free drug is cleared.","w":["Displacement adds to the free fraction, it does not lower it.","Binding is changed by displacement, so there is a change in free concentration.","Half-life changes little; the main change is a temporary rise in the free fraction."]}],["q-fcps-pha6-03","Which drug is mainly excreted unchanged by the kidney and needs dose adjustment in renal failure?",["Gentamicin","Warfarin","Phenytoin","Diazepam"],"Lithium and digoxin are also renally cleared.",{"m":"Aminoglycosides are small polar molecules filtered by the glomerulus and not metabolised, so accumulation occurs when GFR falls, with a risk of nephrotoxicity and ototoxicity.","w":["Warfarin is metabolised by hepatic CYP2C9.","Phenytoin is metabolised in the liver by CYP2C9 and 2C19.","Diazepam is metabolised in the liver to active metabolites."]}],["q-fcps-pha6-04","Which of the following drugs follows saturable (Michaelis-Menten) kinetics at therapeutic doses?",["Phenytoin","Amoxicillin","Gentamicin","Atenolol"],"A small dose increase causes a disproportionate rise in plasma concentration.",{"m":"At therapeutic concentrations phenytoin saturates its hepatic hydroxylating enzymes, so elimination becomes zero-order and small dose increases give disproportionate rises in level.","w":["Elimination is first-order at therapeutic doses; a constant fraction is removed.","Eliminated by renal filtration and secretion with first-order kinetics.","Renally excreted with first-order kinetics."]}],["q-fcps-pha6-05","Enzyme induction by rifampicin reduces the effect of:",["Oral contraceptives and warfarin","Penicillin","Gentamicin","Atenolol"],"Women need alternative contraception during rifampicin therapy.",{"m":"Rifampicin induces CYP3A4 and CYP2C9, which speeds the metabolism of ethinyl oestradiol and warfarin and lowers their effect.","w":["Penicillin is cleared by renal tubular secretion, not by CYP enzymes.","Aminoglycosides are excreted unchanged by the kidney.","Atenolol is excreted renally and is not a CYP substrate."]}],["q-fcps-pha6-06","Which drug is a cytochrome P450 inducer and may cause osteomalacia?",["Phenytoin","Valproate","Levetiracetam","Gabapentin"],"Induction increases vitamin D catabolism.",{"m":"Phenytoin induces hepatic enzymes, which increases catabolism of vitamin D, giving low calcium and osteomalacia.","w":["Valproate is an enzyme inhibitor rather than an inducer.","Levetiracetam has no enzyme-inducing effect.","Gabapentin is excreted unchanged and does not induce enzymes."]}],["q-fcps-pha6-07","Grapefruit juice increases the levels of some drugs by inhibiting:",["Intestinal CYP3A4","CYP2D6","CYP2C9","P-glycoprotein inducers"],"Examples are simvastatin, felodipine and ciclosporin.",{"m":"Furanocoumarins in grapefruit irreversibly inhibit CYP3A4 in the enterocyte, so less first-pass metabolism occurs and the bioavailability of statins and calcium channel blockers rises.","w":["CYP2D6 is not significantly affected by grapefruit.","CYP2C9 is not the main target of grapefruit.","P-glycoprotein inducers would lower, not raise, drug levels and grapefruit is not an inducer."]}],["q-fcps-pha6-08","Which is the most common type of adverse drug reaction?",["Type A (dose-related, predictable)","Type B (idiosyncratic)","Type C (chronic)","Type D (delayed)"],"Type B reactions include anaphylaxis to penicillin.",{"m":"Type A reactions are exaggerations of the pharmacological effect of the drug, and so they are dose-dependent and common.","w":["Type B reactions are unpredictable and uncommon, such as anaphylaxis.","Type C relates to long-term use and is uncommon.","Type D (delayed), such as teratogenesis, is uncommon."]}],["q-fcps-pha6-09","Thalidomide causes:",["Phocomelia","Neural tube defects","Cleft palate only","Deafness"],"It is used now for multiple myeloma and erythema nodosum leprosum.",{"m":"Thalidomide acts by degrading developmental transcription factors through cereblon, and exposure at 20 to 36 days of gestation disrupts limb bud formation.","w":["Neural tube defects are associated with valproate and carbamazepine.","Orofacial clefts are linked to phenytoin and steroids, and the effect is not exclusive.","Deafness is a feature of aminoglycosides, and of rubella."]}],["q-fcps-pha6-10","Which drug in pregnancy causes fetal Ebstein anomaly?",["Lithium","Phenytoin","Warfarin","Valproate"],"Warfarin causes nasal hypoplasia and stippled epiphyses.",{"m":"Lithium exposure in the first trimester interferes with cardiac development, and the tricuspid valve is displaced into the right ventricle.","w":["Phenytoin gives fetal hydantoin syndrome.","Warfarin gives nasal hypoplasia and stippled epiphyses.","Valproate gives neural tube defects."]}],["q-fcps-pha6-11","Which drug causes ototoxicity and congenital deafness in the fetus?",["Streptomycin","Penicillin","Erythromycin","Metronidazole"],"Aminoglycosides should be avoided in pregnancy.",{"m":"Aminoglycosides cross the placenta and damage the hair cells and eighth nerve of the fetus through free radical injury.","w":["Penicillin is safe in pregnancy.","Erythromycin (not the estolate) is generally safe in pregnancy.","Metronidazole is not linked to fetal deafness."]}],["q-fcps-pha6-12","Isoprenaline acts on:",["Beta-1 and beta-2 receptors","Alpha-1 receptors","Alpha-2 receptors","Dopamine receptors only"],"It increases the heart rate and causes vasodilation, lowering diastolic pressure.",{"m":"Isoprenaline is a non-selective beta agonist, so it increases heart rate and contractility (beta-1) and vasodilates and bronchodilates (beta-2).","w":["It has negligible alpha-1 activity and so does not cause vasoconstriction.","Alpha-2 effects are absent.","It has no dopamine receptor action."]}],["q-fcps-pha6-13","Dobutamine acts mainly on:",["Beta-1 receptors","Beta-2 receptors","Alpha-1 receptors","D1 receptors"],"It is used in acute heart failure and cardiogenic shock.",{"m":"Dobutamine mainly stimulates cardiac beta-1 receptors, raising contractility with less rise in heart rate and little vasoconstriction.","w":["Beta-2 action is weak and not the primary effect.","Alpha-1 stimulation is minimal.","Dopamine receptor action is not the main effect."]}],["q-fcps-pha6-14","Noradrenaline infusion results in:",["Rise in blood pressure with reflex bradycardia","Fall in blood pressure","Tachycardia with vasodilation","Bronchodilation"],"Unlike adrenaline, which can lower diastolic pressure through beta-2 vasodilation at low doses, noradrenaline has little beta-2 action.",{"m":"Noradrenaline stimulates alpha-1 receptors, causing vasoconstriction and a rise in blood pressure, and the baroreceptor reflex slows the heart.","w":["Alpha-1 mediated vasoconstriction raises the pressure.","Heart rate falls through the reflex, and there is no beta-2 vasodilation.","Beta-2 action is minimal, so no bronchodilation occurs."]}],["q-fcps-pha6-15","Dopamine at low doses (1 to 3 microgram/kg/min) acts on:",["D1 receptors, causing renal vasodilation","Beta-1 receptors","Alpha-1 receptors","Muscarinic receptors"],"At high doses alpha-1 vasoconstriction predominates.",{"m":"Low-dose dopamine stimulates D1 receptors in renal and mesenteric vessels and raises cAMP, which causes vasodilation.","w":["Beta-1 effects occur at moderate doses of 3 to 10 microgram/kg/min.","Alpha-1 vasoconstriction occurs at high doses.","It has no muscarinic action."]}],["q-fcps-pha6-16","Which drug is a first-line vasopressor in septic shock?",["Noradrenaline","Dopamine","Dobutamine","Phenylephrine"],"Vasopressin may be added.",{"m":"Noradrenaline raises mean arterial pressure through alpha-1 vasoconstriction with some beta-1 inotropy, and is the guideline first-line choice.","w":["It is associated with more arrhythmias and is a second-line choice.","Dobutamine is an inotrope that may lower vascular resistance and does not correct vasodilatory shock.","Pure alpha agonism reduces cardiac output and is not first-line."]}],["q-fcps-pha6-17","Atropine is used in all EXCEPT:",["Reducing blood pressure","Sinus bradycardia","Organophosphate poisoning","Pre-anaesthetic medication to reduce secretions"],"It causes tachycardia, dry mouth, mydriasis, urinary retention and hyperthermia.",{"m":"Atropine blocks muscarinic receptors, which causes tachycardia and no fall in blood pressure; the other uses depend on blocking vagal or cholinergic effects.","w":["Blocking vagal tone raises heart rate in sinus bradycardia.","It antagonises excess acetylcholine at muscarinic receptors.","It reduces salivary and bronchial secretions through muscarinic blockade."]}],["q-fcps-pha6-18","The antimuscarinic drug of choice for motion sickness is:",["Hyoscine (scopolamine)","Ipratropium","Atropine","Pirenzepine"],"Transdermal patches are available.",{"m":"Hyoscine blocks muscarinic receptors in the vestibular nuclei and vomiting centre, and it crosses the blood-brain barrier well.","w":["Ipratropium is a quaternary compound that does not cross into the brain.","Atropine is less effective centrally and has a shorter central effect than hyoscine.","Pirenzepine is an M1-selective agent used for gastric acid."]}],["q-fcps-pha6-19","Oxybutynin is used for:",["Overactive bladder","Urinary retention","Glaucoma","Peptic ulcer"],"Adverse effects are dry mouth and constipation.",{"m":"Oxybutynin blocks muscarinic M3 receptors in the detrusor, reducing involuntary contractions.","w":["Retention needs a cholinergic agonist, and an antimuscarinic worsens it.","Antimuscarinics raise intraocular pressure and are contraindicated in angle-closure glaucoma.","Acid-reducing antimuscarinics are not used much because of side effects."]}],["q-fcps-pha6-20","Bethanechol is used for:",["Postoperative urinary retention","Overactive bladder","Asthma","Myasthenia gravis"],"It is a muscarinic agonist resistant to cholinesterase.",{"m":"Bethanechol is a muscarinic agonist that is resistant to cholinesterase, contracting the detrusor and relaxing the sphincter.","w":["Overactive bladder needs a blocker; an agonist worsens it.","It is a muscarinic agent and is not used for bronchodilation (it causes bronchospasm).","Myasthenia needs nicotinic receptor stimulation, which is improved by cholinesterase inhibitors."]}],["q-fcps-pha6-21","Edrophonium is used for:",["Diagnosis of myasthenia gravis (Tensilon test)","Long-term treatment","Poisoning","Glaucoma"],"It has a very short duration of action.",{"m":"Edrophonium inhibits acetylcholinesterase reversibly for a few minutes, so that acetylcholine accumulates and the weakness improves transiently in myasthenia.","w":["Its duration is too short for chronic therapy.","Poisoning from organophosphates needs atropine and pralidoxime.","Glaucoma uses topical pilocarpine or other agents."]}],["q-fcps-pha6-22","Which neuromuscular blocker is a depolarising agent?",["Suxamethonium","Atracurium","Rocuronium","Vecuronium"],"It causes fasciculations, hyperkalaemia and muscle pains.",{"m":"Suxamethonium acts as an agonist at the nicotinic receptor and persistently depolarises the endplate, causing fasciculations and then paralysis.","w":["Atracurium competitively blocks the nicotinic receptor without depolarising.","Rocuronium is a non-depolarising competitive antagonist.","Vecuronium is a non-depolarising competitive antagonist."]}],["q-fcps-pha6-23","Sugammadex reverses:",["Rocuronium and vecuronium","Suxamethonium","Atracurium","Midazolam"],"It encapsulates the aminosteroid blockers.",{"m":"Sugammadex is a modified cyclodextrin that encapsulates aminosteroid blockers in plasma and reverses the neuromuscular block.","w":["Suxamethonium is broken down by plasma cholinesterase and is not encapsulated.","Atracurium is a benzylisoquinolinium compound that is not bound well.","Benzodiazepines are reversed by flumazenil."]}],["q-fcps-pha6-24","Which drug is a centrally acting muscle relaxant that acts via GABA-B receptors?",["Baclofen","Dantrolene","Tizanidine","Diazepam"],"Dantrolene acts directly on skeletal muscle by blocking ryanodine receptors.",{"m":"Baclofen activates presynaptic GABA-B receptors in the spinal cord and reduces excitatory transmitter release, relieving spasticity.","w":["Dantrolene blocks the ryanodine receptor in muscle.","Tizanidine acts on central alpha-2 receptors.","Diazepam acts on GABA-A receptors."]}],["q-fcps-pha6-25","Benzodiazepines act by:",["Increasing the frequency of chloride channel opening at GABA-A receptors","Increasing the duration of channel opening","Blocking sodium channels","Blocking NMDA receptors"],"Barbiturates increase the duration of channel opening.",{"m":"Benzodiazepines bind between the alpha and gamma subunits of the GABA-A receptor and increase the frequency of chloride channel opening, causing hyperpolarisation.","w":["Barbiturates act by lengthening channel opening.","Phenytoin and carbamazepine block sodium channels.","Ketamine and memantine block NMDA receptors."]}],["q-fcps-pha6-26","Which benzodiazepine has no active metabolites and is preferred in the elderly and in liver disease?",["Lorazepam","Diazepam","Chlordiazepoxide","Flurazepam"],"Oxazepam and temazepam are also conjugated directly.",{"m":"Lorazepam is conjugated by glucuronidation directly, so it has no active metabolites and does not accumulate in the elderly and in liver disease.","w":["Diazepam forms desmethyldiazepam, which is active and long-acting.","Chlordiazepoxide has several active metabolites.","Flurazepam yields a very long-acting active metabolite."]}],["q-fcps-pha6-27","Zolpidem acts on:",["BZ1 (omega-1) subunit of GABA-A","GABA-B","Histamine receptors","Melatonin receptors"],"It has minimal anxiolytic and anticonvulsant effects.",{"m":"Zolpidem binds selectively to the alpha-1 subunit of GABA-A, giving hypnotic action with little muscle relaxant or anticonvulsant effect.","w":["GABA-B receptors are the target of baclofen.","Antihistamines are sedating through H1 blockade, which is not the action of zolpidem.","Ramelteon acts on melatonin receptors."]}],["q-fcps-pha6-28","Buspirone is an anxiolytic that acts as a:",["5-HT1A partial agonist","GABA-A agonist","Dopamine antagonist","Beta blocker"],"It has a delayed onset and no sedation or dependence.",{"m":"Buspirone partially stimulates presynaptic and postsynaptic 5-HT1A receptors, which reduces anxiety after 1 to 2 weeks without sedation.","w":["It does not act on GABA-A, hence no sedation or dependence.","It is not a dopamine antagonist and is not an antipsychotic.","Beta blockers reduce somatic symptoms but are not its mechanism."]}],["q-fcps-pha6-29","Which antidepressant is associated with weight gain and sedation?",["Mirtazapine","Fluoxetine","Bupropion","Venlafaxine"],"Bupropion is associated with weight loss and seizures at high doses.",{"m":"Mirtazapine blocks alpha-2 autoreceptors and 5-HT2 and 5-HT3 receptors, and its strong H1 blockade causes sedation and weight gain.","w":["Fluoxetine inhibits serotonin reuptake and tends to cause activation or weight loss.","Bupropion inhibits noradrenaline and dopamine reuptake and is not sedating.","Venlafaxine is an SNRI and is associated with hypertension."]}],["q-fcps-pha6-30","SSRIs may cause:",["Sexual dysfunction and serotonin syndrome","Hypertensive crisis with cheese","Cardiotoxicity in overdose as the main effect","Marked antimuscarinic effects"],"Tricyclics cause antimuscarinic effects and cardiotoxicity.",{"m":"SSRIs increase serotonin at synapses; this causes sexual dysfunction through 5-HT2 stimulation, and toxicity leads to serotonin syndrome.","w":["Tyramine reactions arise with MAO inhibitors.","Cardiotoxicity in overdose is typical of tricyclics because of sodium channel blockade.","Antimuscarinic effects are typical of tricyclics."]}],["q-fcps-pha6-31","The features of serotonin syndrome include:",["Hyperthermia, clonus and agitation","Bradycardia and hypothermia","Flaccid paralysis","Miosis and bradycardia"],"Cyproheptadine is the antidote.",{"m":"Excess 5-HT stimulation of 5-HT2A and 5-HT1A receptors causes autonomic and neuromuscular hyperactivity, including clonus and hyperthermia.","w":["Autonomic hyperactivity gives tachycardia and hyperthermia.","Excess serotonin causes hyperreflexia and rigidity instead of flaccidity.","Mydriasis rather than miosis is seen."]}],["q-fcps-pha6-32","Which antipsychotic is a partial agonist at D2 receptors?",["Aripiprazole","Haloperidol","Chlorpromazine","Olanzapine"],"It has fewer extrapyramidal side effects and less hyperprolactinaemia.",{"m":"Aripiprazole is a partial agonist at D2 receptors, so it reduces dopamine activity where it is high and increases it where it is low.","w":["Haloperidol is a full D2 antagonist.","Chlorpromazine is a full D2 antagonist.","Olanzapine is a D2 and 5-HT2A antagonist."]}],["q-fcps-pha6-33","Which antipsychotic is most associated with weight gain and metabolic syndrome?",["Olanzapine","Haloperidol","Ziprasidone","Aripiprazole"],"Ziprasidone prolongs the QT interval.",{"m":"Olanzapine blocks H1 and 5-HT2C receptors, which increases appetite and causes insulin resistance and dyslipidaemia.","w":["Haloperidol has little effect on weight and mainly causes extrapyramidal effects.","Ziprasidone is relatively weight neutral but prolongs the QT interval.","Aripiprazole has the lowest weight gain among the atypicals."]}],["q-fcps-pha6-34","Acute dystonia from antipsychotics is treated with:",["Benztropine or procyclidine","Haloperidol","Levodopa","Diazepam only"],"Tardive dyskinesia may follow long-term use and does not respond to anticholinergics.",{"m":"Antimuscarinics restore the balance between dopamine and acetylcholine in the striatum, which is lost when D2 receptors are blocked.","w":["Another D2 blocker would worsen dystonia.","Levodopa could worsen psychosis and is not the standard treatment.","A benzodiazepine alone is less effective than anticholinergics."]}],["q-fcps-pha6-35","Hyperprolactinaemia is caused by:",["Dopamine D2 antagonists such as metoclopramide and risperidone","Bromocriptine","Cabergoline","Levodopa"],"It causes galactorrhoea and amenorrhoea.",{"m":"D2 receptor blockade removes the inhibitory effect of dopamine on lactotrophs in the pituitary, which raises prolactin.","w":["Bromocriptine is a D2 agonist and lowers prolactin.","Cabergoline is a D2 agonist and lowers prolactin.","Levodopa increases dopamine and suppresses prolactin."]}],["q-fcps-pha6-36","Donepezil is used for:",["Alzheimer disease","Parkinson disease","Schizophrenia","Epilepsy"],"It is a reversible acetylcholinesterase inhibitor, and memantine is an NMDA antagonist.",{"m":"Donepezil inhibits acetylcholinesterase reversibly in the CNS, which increases acetylcholine and improves cognition in Alzheimer disease.","w":["Parkinson disease is treated by increasing dopamine.","Schizophrenia is treated with D2 antagonists.","It has no anticonvulsant action."]}],["q-fcps-pha6-37","Sumatriptan acts as an agonist at:",["5-HT1B/1D receptors","5-HT3 receptors","5-HT2A receptors","5-HT4 receptors"],"It is contraindicated in coronary artery disease.",{"m":"Sumatriptan stimulates 5-HT1B receptors (cranial vasoconstriction) and 5-HT1D receptors (inhibition of trigeminal CGRP release), which aborts migraine.","w":["5-HT3 is the target of ondansetron.","5-HT2A is targeted by atypical antipsychotics.","5-HT4 is targeted by prucalopride, which increases motility."]}],["q-fcps-pha6-38","Which drug is used for migraine prophylaxis?",["Propranolol","Sumatriptan","Ergotamine","Paracetamol"],"Topiramate and amitriptyline are also used.",{"m":"Propranolol reduces the frequency of migraine, probably through blocking beta receptors in the vasculature and brain.","w":["Sumatriptan is for acute attacks, not for prevention.","Ergotamine is for acute attacks.","Paracetamol is an acute analgesic."]}],["q-fcps-pha6-39","Which anticonvulsant causes weight loss and kidney stones?",["Topiramate","Valproate","Gabapentin","Phenobarbital"],"It inhibits carbonic anhydrase.",{"m":"Topiramate blocks sodium channels, enhances GABA and weakly inhibits carbonic anhydrase, which causes metabolic acidosis, alkaline urine and stone formation, with appetite suppression.","w":["Valproate causes weight gain.","Gabapentin typically causes weight gain.","Phenobarbital causes sedation and enzyme induction."]}],["q-fcps-pha6-40","Which drug is the first-line treatment of trigeminal neuralgia?",["Carbamazepine","Phenytoin","Valproate","Morphine"],"It blocks sodium channels.",{"m":"Carbamazepine blocks voltage-gated sodium channels and reduces the abnormal repetitive firing of the trigeminal nerve.","w":["Phenytoin has similar action but is less effective and a second-line option.","Valproate is not first-line for this pain.","Opioids are not effective in neuropathic trigeminal pain."]}],["q-fcps-pha6-41","Vigabatrin causes:",["Visual field defects","Gingival hyperplasia","Hirsutism","Hepatotoxicity as main effect"],"It inhibits GABA transaminase.",{"m":"Vigabatrin irreversibly inhibits GABA transaminase, so GABA accumulates; GABA accumulation in the retina leads to irreversible peripheral visual field constriction.","w":["Gingival hyperplasia is a feature of phenytoin.","Hirsutism is a feature of phenytoin.","Hepatotoxicity is a feature of valproate."]}],["q-fcps-pha6-42","Which drug is a selective COX-2 inhibitor with a sulphonamide group, contraindicated in sulpha allergy?",["Celecoxib","Ibuprofen","Naproxen","Ketorolac"],"Increased cardiovascular risk limits its use.",{"m":"Celecoxib selectively inhibits COX-2, which spares COX-1 gastric prostaglandins; its sulphonamide moiety carries a risk of allergy in sulpha-allergic patients.","w":["Ibuprofen is a non-selective NSAID with no sulphonamide group.","Naproxen is non-selective.","Ketorolac is non-selective and potent."]}],["q-fcps-pha6-43","Ketorolac is mainly used as:",["A potent short-term analgesic","An anti-inflammatory for chronic arthritis","An antipyretic in children","A gout prophylactic"],"It has a high risk of gastrointestinal bleeding and renal toxicity.",{"m":"Ketorolac is a non-selective COX inhibitor with strong analgesic action and so is limited to 5 days because of gastrointestinal and renal toxicity.","w":["It is used short-term, not for chronic inflammation.","Aspirin and ibuprofen are avoided or used with caution in children; paracetamol is preferred.","Colchicine is used for gout prophylaxis."]}],["q-fcps-pha6-44","Paracetamol toxicity in overdose is due to:",["NAPQI, with depletion of glutathione","Direct renal toxicity","COX inhibition","Hypersensitivity"],"Centrilobular hepatic necrosis follows.",{"m":"At high doses the saturated glucuronidation and sulphation pathways shunt paracetamol to CYP2E1, producing NAPQI which depletes glutathione and binds hepatocyte proteins.","w":["Hepatic, not renal, necrosis is the dominant toxicity.","COX inhibition does not explain the toxicity.","Toxicity is dose-dependent and not an allergic reaction."]}],["q-fcps-pha6-45","Aspirin should be avoided in children with viral illness because of:",["Reye syndrome","Kawasaki disease","Stevens-Johnson syndrome","Bone marrow suppression"],"Low-dose aspirin is still used in Kawasaki disease.",{"m":"Salicylates are suspected to damage mitochondrial beta-oxidation in the liver and brain after viral infection, causing Reye syndrome with hepatic failure and encephalopathy.","w":["Aspirin is used in Kawasaki disease, not a reason to avoid it.","Stevens-Johnson is a rare reaction and not the reason for the warning.","Marrow suppression is not typical of aspirin."]}],["q-fcps-pha6-46","In low doses, aspirin inhibits platelet aggregation by blocking:",["Thromboxane A2 synthesis","Prostacyclin synthesis","Phosphodiesterase","ADP receptor"],"Endothelial cells can resynthesise COX, while platelets cannot.",{"m":"Low-dose aspirin irreversibly acetylates platelet COX-1, which prevents thromboxane A2 synthesis for the platelet life (7 to 10 days) since platelets cannot make new enzyme.","w":["Endothelial prostacyclin is spared at low doses because endothelial cells regenerate COX.","Phosphodiesterase inhibition is the action of dipyridamole.","The ADP receptor is blocked by clopidogrel."]}],["q-fcps-pha6-47","Allopurinol is contraindicated during an acute attack of gout because it:",["May prolong or precipitate attacks when started during one","Is nephrotoxic","Is ineffective","Increases uric acid"],"Colchicine or NSAID prophylaxis should accompany initiation.",{"m":"Starting allopurinol changes urate pools and mobilises crystals from tissues, so flares may be precipitated or prolonged unless colchicine or an NSAID covers initiation.","w":["Nephrotoxicity is not the reason for deferring it.","It is effective in lowering urate but not for an acute flare.","It lowers rather than increases uric acid synthesis."]}],["q-fcps-pha6-48","Probenecid acts by:",["Inhibiting the renal tubular reabsorption of uric acid","Inhibiting xanthine oxidase","Breaking down uric acid","Inhibiting neutrophil migration"],"It also reduces penicillin secretion and prolongs its action.",{"m":"Probenecid inhibits URAT1 and OAT in the proximal tubule, increasing the uric acid excretion.","w":["This is the action of allopurinol and febuxostat.","Uricase (rasburicase) converts urate to allantoin.","Colchicine reduces neutrophil migration."]}],["q-fcps-pha6-49","Which drug is a first-line in the treatment of rheumatoid arthritis flares requiring a bridge until DMARDs act?",["Low-dose prednisolone","Gold","Allopurinol","Colchicine"],"Biologic agents include TNF inhibitors.",{"m":"Low-dose glucocorticoids suppress transcription of inflammatory cytokines and provide rapid control while slow-acting DMARDs take effect.","w":["Gold is a slow-acting DMARD, not a bridge.","Allopurinol lowers uric acid and has no role in RA.","Colchicine is used for gout."]}],["q-fcps-pha6-50","Bisphosphonates act by:",["Inhibiting osteoclast-mediated bone resorption","Stimulating osteoblasts","Increasing intestinal calcium absorption","Inhibiting PTH"],"Oesophagitis and osteonecrosis of the jaw are adverse effects.",{"m":"Bisphosphonates bind hydroxyapatite and are taken up by osteoclasts, where nitrogen-containing drugs inhibit farnesyl pyrophosphate synthase and cause osteoclast apoptosis.","w":["Teriparatide intermittently stimulates bone formation.","Calcitriol increases calcium absorption.","Cinacalcet affects PTH secretion, not bisphosphonates."]}],["q-fcps-pha6-51","Teriparatide is:",["A recombinant fragment of parathyroid hormone that is anabolic when given intermittently","A bisphosphonate","A RANKL inhibitor","A calcitonin analogue"],"Denosumab is a monoclonal antibody against RANKL.",{"m":"Intermittent PTH(1-34) stimulates osteoblasts more than osteoclasts and so is anabolic, whereas continuous exposure causes bone resorption.","w":["Bisphosphonates are pyrophosphate analogues.","Denosumab is a RANKL antibody.","Calcitonin analogues inhibit osteoclasts."]}],["q-fcps-pha6-52","Levothyroxine should be taken:",["On an empty stomach, apart from calcium and iron","With meals","With antacids","At bedtime with milk"],"Absorption is reduced by calcium, iron and aluminium.",{"m":"Calcium, iron and aluminium bind levothyroxine in the gut and reduce its absorption, and food also impairs absorption.","w":["Food reduces absorption.","Antacids containing aluminium bind levothyroxine.","Milk contains calcium, which reduces absorption."]}],["q-fcps-pha6-53","Propylthiouracil blocks:",["Thyroid peroxidase and peripheral conversion of T4 to T3","Iodine uptake","TSH receptor","Release of preformed hormone only"],"Carbimazole does not block peripheral conversion.",{"m":"PTU inhibits thyroid peroxidase, which blocks iodine organification and coupling, and also inhibits peripheral 5'-deiodinase.","w":["Perchlorate blocks iodide uptake through the sodium-iodide symporter.","Graves disease antibodies, not the drug, act at the TSH receptor.","Lithium and iodide reduce hormone release."]}],["q-fcps-pha6-54","Which drug is used for diabetes insipidus of central origin?",["Desmopressin","Thiazide","Demeclocycline","Tolvaptan"],"Thiazides are used for nephrogenic diabetes insipidus.",{"m":"Desmopressin is a synthetic V2 agonist that inserts aquaporin-2 into the collecting duct, replacing the missing ADH.","w":["Thiazides paradoxically reduce urine volume in nephrogenic disease but are not first-line for central disease.","Demeclocycline causes nephrogenic diabetes insipidus and is used for SIADH.","Tolvaptan blocks V2 receptors and would worsen the polyuria."]}],["q-fcps-pha6-55","Tolvaptan acts as:",["A V2 receptor antagonist","A V1 agonist","An ADH analogue","An aldosterone antagonist"],"It is used in SIADH and hyponatraemia.",{"m":"Tolvaptan competitively blocks V2 receptors in the collecting duct, which prevents aquaporin-2 insertion and produces free-water excretion (aquaresis).","w":["V1 stimulation causes vasoconstriction, which tolvaptan does not do.","Desmopressin is the ADH analogue.","Spironolactone is the aldosterone antagonist."]}],["q-fcps-pha6-56","Octreotide is used in:",["Acromegaly, carcinoid and variceal bleeding","Cushing syndrome","Hypoglycaemia","Diabetes insipidus"],"It is a somatostatin analogue.",{"m":"Octreotide is a somatostatin analogue that inhibits release of growth hormone, vasoactive peptides and splanchnic blood flow, which helps variceal bleeding.","w":["Cushing syndrome is treated with steroidogenesis inhibitors.","It can cause hypoglycaemia by suppressing glucagon, and is used for insulinoma, not for treating hypoglycaemia.","Diabetes insipidus needs desmopressin."]}],["q-fcps-pha6-57","Which insulin is a rapid-acting analogue?",["Insulin lispro","NPH insulin","Insulin glargine","Insulin detemir"],"Glargine is a long-acting basal insulin without a peak.",{"m":"Lispro has a swapped lysine and proline in the B chain, which reduces hexamer formation so it is absorbed rapidly.","w":["NPH is an intermediate-acting insulin because of protamine.","Glargine precipitates at tissue pH and gives slow release.","Detemir binds albumin through a fatty acid, giving a prolonged effect."]}],["q-fcps-pha6-58","Which oral hypoglycaemic is associated with weight loss and pancreatitis risk when given by injection?",["Liraglutide (GLP-1 agonist)","Glimepiride","Pioglitazone","Insulin"],"GLP-1 agonists reduce appetite and delay gastric emptying.",{"m":"Liraglutide activates GLP-1 receptors, which increases glucose-dependent insulin release, suppresses glucagon, delays gastric emptying and reduces appetite.","w":["Glimepiride closes K-ATP channels and causes weight gain.","Pioglitazone causes fluid retention and weight gain.","Insulin promotes weight gain."]}],["q-fcps-pha6-59","Acarbose acts by:",["Inhibiting intestinal alpha-glucosidase","Stimulating insulin release","Increasing insulin sensitivity","Inhibiting gluconeogenesis"],"It causes flatulence.",{"m":"Acarbose competitively inhibits alpha-glucosidase at the brush border, so carbohydrate digestion is delayed and postprandial glucose peaks are reduced; undigested sugar causes fermentation and flatulence.","w":["Sulphonylureas stimulate insulin release.","Metformin and glitazones increase insulin sensitivity.","Metformin inhibits hepatic gluconeogenesis."]}],["q-fcps-pha6-60","Which anticoagulant requires no routine laboratory monitoring and acts by directly inhibiting factor Xa?",["Rivaroxaban","Warfarin","Heparin","Dabigatran"],"Dabigatran is a direct thrombin inhibitor.",{"m":"Rivaroxaban directly inhibits free and clot-bound factor Xa, so it gives a predictable anticoagulant effect without routine monitoring.","w":["Warfarin needs INR monitoring.","Unfractionated heparin needs aPTT monitoring.","Dabigatran inhibits thrombin, not factor Xa."]}],["q-fcps-pha6-61","Fondaparinux acts by:",["Selective factor Xa inhibition through antithrombin","Direct thrombin inhibition","Vitamin K antagonism","Plasminogen activation"],"It does not cause heparin-induced thrombocytopenia."],["q-fcps-pha6-62","Tranexamic acid acts as:",["An antifibrinolytic","A procoagulant factor","An antiplatelet","A thrombolytic"],"It inhibits plasminogen activation."],["q-fcps-pha6-63","Which drug is used for reversal of heparin's effect?",["Protamine sulphate","Vitamin K","Tranexamic acid","Idarucizumab"],"It is positively charged and binds heparin."],["q-fcps-pha6-64","Hydroxyurea is used in sickle cell disease because it:",["Increases fetal haemoglobin","Reduces haemolysis","Increases HbS","Removes iron"],"It inhibits ribonucleotide reductase."],["q-fcps-pha6-65","Erythropoietin therapy may cause:",["Hypertension and thrombosis","Hypotension","Neutropenia","Thrombocytopenia"],"It is used in anaemia of chronic kidney disease."],["q-fcps-pha6-66","Filgrastim is used to:",["Increase neutrophil count after chemotherapy","Increase red cells","Increase platelets","Suppress immunity"],"It is a G-CSF analogue."],["q-fcps-pha6-67","Which drug can cause Stevens-Johnson syndrome and is linked to HLA-B*5701 hypersensitivity?",["Abacavir","Zidovudine","Lamivudine","Tenofovir"],"HLA-B*5701 testing is done before abacavir; carbamazepine is linked to HLA-B*1502."],["q-fcps-pha6-68","The antiviral drug that inhibits viral neuraminidase is:",["Oseltamivir","Aciclovir","Amantadine","Ribavirin"],"It should be started within 48 hours of the onset of influenza."],["q-fcps-pha6-69","Ganciclovir is used for:",["Cytomegalovirus infection","Herpes simplex","Influenza","Hepatitis B"],"Neutropenia is its main toxicity."],["q-fcps-pha6-70","Which drug is used in chronic hepatitis B and also has anti-HIV activity?",["Tenofovir","Ribavirin","Sofosbuvir","Oseltamivir"],"Sofosbuvir is an NS5B polymerase inhibitor used in hepatitis C."],["q-fcps-pha6-71","Efavirenz belongs to:",["Non-nucleoside reverse transcriptase inhibitors","Protease inhibitors","Integrase inhibitors","Fusion inhibitors"],"It may cause vivid dreams and is teratogenic in early pregnancy."],["q-fcps-pha6-72","Ritonavir is used with other protease inhibitors as a:",["CYP3A4 inhibitor (booster)","CYP3A4 inducer","Reverse transcriptase inhibitor","Entry inhibitor"],"Raltegravir and dolutegravir are integrase inhibitors."],["q-fcps-pha6-73","Which antimalarial can cause retinopathy with long-term use and QT prolongation?",["Chloroquine","Artesunate","Atovaquone","Doxycycline"],"It is also used in rheumatoid arthritis and lupus, and primaquine is the one most associated with G6PD haemolysis."],["q-fcps-pha6-74","Mefloquine is associated with:",["Neuropsychiatric effects","Hearing loss","Hepatic necrosis","Pulmonary fibrosis"],"It is contraindicated in patients with seizures or psychiatric disease."],["q-fcps-pha6-75","Which drug is used for toxoplasmosis in combination with sulphadiazine?",["Pyrimethamine","Metronidazole","Chloroquine","Albendazole"],"Folinic acid prevents marrow suppression."],["q-fcps-pha6-76","Albendazole acts by:",["Inhibiting microtubule polymerisation in helminths","Opening chloride channels","Blocking acetylcholine receptors","Inhibiting folate synthesis"],"It is used in hydatid disease and neurocysticercosis."],["q-fcps-pha6-77","Diloxanide furoate is used for:",["Luminal amoebiasis","Amoebic liver abscess alone","Giardiasis","Trichomoniasis"],"Metronidazole treats tissue amoebiasis."],["q-fcps-pha6-78","Which antibiotic is bacteriostatic and acts on the 50S ribosomal subunit?",["Clindamycin","Gentamicin","Tetracycline","Penicillin"],"Tetracyclines act on the 30S subunit."],["q-fcps-pha6-79","Pseudomembranous colitis is most associated with:",["Clindamycin","Vancomycin","Doxycycline","Metronidazole"],"Cephalosporins and fluoroquinolones are also implicated."],["q-fcps-pha6-80","Which drug is the drug of choice for MRSA infection?",["Vancomycin","Flucloxacillin","Cefazolin","Ampicillin"],"Linezolid and daptomycin are alternatives."],["q-fcps-pha6-81","Which drug is used to treat leprosy and may cause haemolysis and methaemoglobinaemia?",["Dapsone","Rifampicin","Clofazimine","Thalidomide"],"Clofazimine causes skin discolouration."],["q-fcps-pha6-82","Which of the following penicillins is resistant to penicillinase?",["Flucloxacillin","Ampicillin","Benzylpenicillin","Amoxicillin"],"It is used for staphylococcal infections, and cholestatic jaundice is a rare adverse effect."],["q-fcps-pha6-83","Piperacillin-tazobactam has activity against:",["Pseudomonas aeruginosa","MRSA","Atypical organisms","Viruses"],"Tazobactam is a beta-lactamase inhibitor."],["q-fcps-pha6-84","Aztreonam is a:",["Monobactam active only against aerobic gram-negative bacteria","Carbapenem","Cephalosporin","Penicillin"],"It is safe in penicillin allergy."],["q-fcps-pha6-85","Trimethoprim-sulphamethoxazole acts by:",["Sequential blockade of folate synthesis","Inhibiting DNA gyrase","Inhibiting cell wall synthesis","Inhibiting 50S subunit"],"It is the drug of choice for Pneumocystis jirovecii pneumonia."],["q-fcps-pha6-86","Nitrofurantoin is used for:",["Uncomplicated urinary tract infection","Pyelonephritis","Pneumonia","Septicaemia"],"It can cause pulmonary fibrosis and is avoided in renal impairment."],["q-fcps-pha6-87","Which drug is used as first-line therapy for scabies?",["Permethrin","Lindane","Benzyl benzoate in infants","Malathion in pregnancy"],"Oral ivermectin is an alternative."],["q-fcps-pha6-88","Cyclophosphamide is activated in the:",["Liver by cytochrome P450","Kidney","Blood","Skin"],"It is a prodrug and an alkylating agent."],["q-fcps-pha6-89","Which anticancer drug causes pulmonary fibrosis?",["Bleomycin","Vincristine","Methotrexate","Cisplatin"],"Bleomycin has little bone marrow toxicity."],["q-fcps-pha6-90","5-Fluorouracil acts by inhibiting:",["Thymidylate synthase","Dihydrofolate reductase","Topoisomerase","Ribonucleotide reductase"],"Leucovorin enhances its binding."],["q-fcps-pha6-91","Etoposide inhibits:",["Topoisomerase II","Topoisomerase I","Microtubules","DNA polymerase"],"Irinotecan inhibits topoisomerase I."],["q-fcps-pha6-92","Hydroxychloroquine and sulfasalazine are used in:",["Rheumatoid arthritis","Gout","Osteoporosis","Asthma"],"Sulfasalazine is also used in ulcerative colitis."],["q-fcps-pha6-93","Mycophenolate mofetil inhibits:",["Inosine monophosphate dehydrogenase","Calcineurin","mTOR","Dihydrofolate reductase"],"It selectively blocks lymphocyte purine synthesis."],["q-fcps-pha6-94","Which drug is an IL-2 receptor antagonist used in transplantation?",["Basiliximab","Rituximab","Infliximab","Adalimumab"],"Infliximab and adalimumab are TNF inhibitors."],["q-fcps-pha6-95","Which drug is the first-line for Pneumocystis prophylaxis in HIV?",["Co-trimoxazole","Pentamidine","Dapsone","Atovaquone"],"Pentamidine is an alternative."],["q-fcps-pha6-96","Which drug is a laxative that acts by stimulating enteric nerves and is contraindicated in intestinal obstruction?",["Bisacodyl","Lactulose","Methylcellulose","Docusate"],"Bulk-forming laxatives need adequate fluid intake."],["q-fcps-pha6-97","Ursodeoxycholic acid is used for:",["Dissolving small cholesterol gallstones and primary biliary cholangitis","Pigment stones","Acute cholecystitis","Pancreatitis"],"It decreases cholesterol saturation of bile."],["q-fcps-pha6-98","Orlistat acts by:",["Inhibiting pancreatic and gastric lipases","Suppressing appetite","Increasing metabolic rate","Inhibiting glucose absorption"],"It causes steatorrhoea and decreases the absorption of fat-soluble vitamins."],["q-fcps-pha6-99","Sildenafil is contraindicated with:",["Nitrates","Beta blockers","Diuretics","Statins"],"Both increase cGMP, resulting in severe hypotension."],["q-fcps-pha6-100","Finasteride acts by:",["Inhibiting 5-alpha reductase","Blocking androgen receptors","Blocking alpha-1 receptors","Inhibiting aromatase"],"Flutamide and bicalutamide are androgen receptor antagonists."],["q-fcps-pha6-101","Anastrozole is used in postmenopausal breast cancer as an:",["Aromatase inhibitor","Oestrogen receptor antagonist","GnRH agonist","Progestin"],"Osteoporosis is an important adverse effect."],["q-fcps-pha6-102","Continuous administration of GnRH agonists such as leuprolide results in:",["Suppression of gonadotropins","Increased FSH and LH","Increased testosterone","Ovulation"],"A transient initial surge occurs (flare)."],["q-fcps-pha6-103","Combined oral contraceptives are contraindicated in:",["History of thromboembolism and migraine with aura","Acne","Dysmenorrhoea","Menorrhagia"],"They also protect against ovarian and endometrial cancer."],["q-fcps-pha6-104","Emergency contraception by levonorgestrel is effective when taken within:",["72 hours","7 days","10 days","2 weeks"],"A copper intrauterine device is effective up to 5 days."],["q-fcps-pha6-105","Which prostaglandin analogue is used to maintain patency of the ductus arteriosus?",["Alprostadil","Misoprostol","Dinoprostone","Latanoprost"],"Latanoprost is used for glaucoma."],["q-fcps-pha6-106","Timolol, latanoprost and dorzolamide are used in:",["Open-angle glaucoma","Cataract","Uveitis","Conjunctivitis"],"They reduce aqueous production or increase outflow."],["q-fcps-pha6-107","Which drug is used for acute angle-closure glaucoma?",["Intravenous acetazolamide and mannitol with pilocarpine","Atropine drops","Timolol alone only","Tropicamide"],"Mydriatics are contraindicated."]];
